import type { Listening, Question, Reading, TopicId } from '../types';

type ReadingCategory = 'reading-short' | 'reading-medium' | 'reading-long' | 'reading-information';
type ListeningCategory = 'listening-task' | 'listening-points' | 'listening-outline' | 'listening-expression' | 'listening-response';
type Category = ReadingCategory | ListeningCategory;
type RichReading = Reading & { topicId: TopicId; questionType: ReadingCategory };
type RichListening = Listening & { topicId: TopicId; questionType: ListeningCategory };
type RichQuestion = Question & { topicId: TopicId; questionType: Category };
type Wrong = [text: string, reason: string];
interface Spec { prompt: string; answer: string; reason: string; wrong: [Wrong, Wrong, Wrong]; evidence: string }

export const expandedReadings: RichReading[] = [];
export const expandedListening: RichListening[] = [];
export const expandedPassageQuestions: RichQuestion[] = [];

function addQuestions(id: string, topicId: TopicId, questionType: Category, source: string, specs: Spec[]): string[] {
  return specs.map((spec, index) => {
    const questionId = `q${id}-${index + 1}`;
    if (!source.includes(spec.evidence)) throw new Error(`Evidence is not in ${id}: ${spec.evidence}`);
    const choices: Wrong[] = [[spec.answer, spec.reason], ...spec.wrong];
    const shift = [...questionId].reduce((sum, character) => sum + character.charCodeAt(0), 0) % 4;
    const ordered = [...choices.slice(shift), ...choices.slice(0, shift)];
    const options = ordered.map(([text], position) => ({ id: `${questionId}-${'abcd'[position]}`, text }));
    expandedPassageQuestions.push({ id: questionId, skill: id.startsWith('rx-') ? 'reading' : 'listening', topicId, questionType,
      prompt: spec.prompt, options, correctOptionId: options[ordered.findIndex(choice => choice === choices[0])].id,
      explanations: Object.fromEntries(options.map((option, position) => [option.id, ordered[position][1]])), evidence: spec.evidence,
      ...(id.startsWith('rx-') ? { passageId: id } : { listeningId: id }) });
    return questionId;
  });
}
function read(id: string, title: string, type: Reading['type'], topicId: TopicId, questionType: ReadingCategory, body: string, translation: string, specs: Spec[]): void {
  expandedReadings.push({ id, title, type, topicId, questionType, body, translation, questionIds: addQuestions(id, topicId, questionType, body, specs) });
}
function listen(id: string, title: string, topicId: TopicId, questionType: ListeningCategory, script: string, translation: string, specs: Spec[]): void {
  expandedListening.push({ id, title, topicId, questionType, script, translation, questionIds: addQuestions(id, topicId, questionType, script, specs) });
}

// Original N3-style passages. These are written practice adaptations, not copied official exam items.
read('rx-morning', 'A different meeting point', 'email', 'daily', 'reading-short',
  '美奈さんへ\n明日の朝、一緒に図書館へ行く約束ですが、家の水道を直す人が来ることになったので、私は少し遅れます。先に図書館へ行って、入口の右にある休憩室で待っていてください。駅では待たないでくださいね。修理は九時半に終わる予定です。図書館には十時ごろ着くと思います。もし修理が長くなったら、電話します。飲み物は私が買っていくので、持ってこなくても大丈夫です。\n由衣',
  'Dear Mina, about our plan to go to the library together tomorrow morning: someone will be coming to repair the plumbing at my house, so I will be a little late. Please go to the library first and wait in the lounge to the right of the entrance. Please do not wait at the station. The repair is scheduled to finish at 9:30. I think I will reach the library around 10. If the repair takes longer, I will call. I will buy drinks on the way, so you do not need to bring any. Yui.', [
    { prompt: '美奈さんは、どこで待てばいいですか。', answer: '図書館の入口の右にある休憩室。', reason: 'Yui specifically asks Mina to wait in the lounge to the right of the library entrance.', wrong: [['駅の改札の前。', 'The email explicitly says not to wait at the station.'], ['由衣さんの家の前。', 'The repair happens at Yui’s home, but Mina is told to go to the library first.'], ['図書館の受付の左。', 'The designated place is the lounge on the right of the entrance, not a desk on the left.']], evidence: '入口の右にある休憩室で待っていてください。' },
    { prompt: '由衣さんが遅れる理由は何ですか。', answer: '家の水道の修理があるから。', reason: 'A person is coming to repair Yui’s plumbing, which prevents her from leaving on time.', wrong: [['図書館が九時半まで開かないから。', 'Nine thirty is the expected end of the repair; no opening time is given.'], ['駅で飲み物を売っていないから。', 'Drinks are mentioned as something Yui will bring, not a reason for being late.'], ['美奈さんから電話が来るから。', 'Yui will call Mina only if the repair takes longer.']], evidence: '家の水道を直す人が来ることになったので、私は少し遅れます。' },
    { prompt: '修理が予定より長くなった場合、由衣さんは何をしますか。', answer: '美奈さんに電話する。', reason: 'The email explicitly promises a call if the repair takes longer.', wrong: [['図書館へ行くのをやめる。', 'There is no cancellation plan; Yui says she will call.'], ['美奈さんに飲み物を頼む。', 'Yui has said she will buy the drinks herself.'], ['駅で美奈さんを待つ。', 'Mina is instructed to wait at the library, not at the station.']], evidence: 'もし修理が長くなったら、電話します。' },
  ]);

read('rx-laundry', 'Using the shared laundry room', 'notice', 'home', 'reading-short',
  '共同洗濯室をご利用の皆さんへ\n最近、洗濯が終わっても服が洗濯機に残っていて、次の人が使えないことがあります。終了したら、十五分以内に服を取り出してください。取りに来るのが遅れそうなときは、洗濯を始める前に受付へ相談してください。乾燥機は午後九時まで使えますが、洗濯機を使い始められるのは午後八時までです。洗剤は各自で用意してください。部屋にあるかごは服を運ぶための物なので、家に持ち帰らないでください。',
  'To users of the shared laundry room: recently, clothes have sometimes been left in machines after washing has finished, preventing the next person from using them. Please remove your clothes within fifteen minutes of the cycle ending. If you expect to be late collecting them, consult reception before starting the wash. Dryers may be used until 9 p.m., but washing machines may only be started until 8 p.m. Please supply your own detergent. The baskets in the room are for carrying clothes, so do not take them home.', [
    { prompt: 'このお知らせで、特にお願いしていることは何ですか。', answer: '洗濯が終わったら、早く服を取り出すこと。', reason: 'The problem is finished laundry left in machines, and users are asked to remove it within fifteen minutes.', wrong: [['服は家で乾かすこと。', 'Dryers are available until nine; users are not required to dry clothes at home.'], ['洗濯をする前に必ず受付へ行くこと。', 'Consulting reception is necessary only if collection may be delayed.'], ['洗濯機を十五分だけ使うこと。', 'Fifteen minutes is the collection window after completion, not a washing-cycle limit.']], evidence: '終了したら、十五分以内に服を取り出してください。' },
    { prompt: '午後八時半に洗濯室へ来た人は、何ができますか。', answer: '乾燥機を使う。', reason: 'At 8:30 p.m., starting a wash is prohibited, but the dryer remains available until nine.', wrong: [['新しく洗濯を始める。', 'New washing cycles may only be started until eight.'], ['受付で無料の洗剤をもらう。', 'Users must prepare their own detergent; free detergent is not offered.'], ['かごを家へ持ち帰る。', 'The notice expressly prohibits taking the room’s baskets home.']], evidence: '乾燥機は午後九時まで使えますが、洗濯機を使い始められるのは午後八時までです。' },
    { prompt: '服を取りに来るのが遅れそうな人は、いつ受付へ相談しますか。', answer: '洗濯を始める前。', reason: 'The instruction specifies consulting reception before starting if collection is likely to be late.', wrong: [['洗濯が終わって十五分後。', 'The consultation must happen before starting, not after the collection deadline.'], ['乾燥機を止めた後。', 'The instruction concerns a potentially late collection and does not depend on drying.'], ['次の日の朝。', 'Waiting until the next day would not satisfy the advance-consultation instruction.']], evidence: '洗濯を始める前に受付へ相談してください。' },
  ]);

read('rx-lunch', 'Lunch orders at the office', 'notice', 'food', 'reading-short',
  '金曜日のお弁当について\n今週は、いつもの店がお休みなので、別の店にお弁当を注文します。肉のお弁当は六百円、野菜のお弁当は五百五十円です。どちらもご飯の量は同じです。注文したい人は、木曜日の正午までに受付の紙に名前と種類を書いてください。代金は金曜日にお弁当を受け取るときに払います。注文の変更は木曜日の午前中だけ受け付けます。飲み物は付いていないので、必要な人は自分で用意してください。',
  'About Friday’s boxed lunches: our usual shop is closed this week, so we will order from another shop. The meat lunch costs 600 yen, and the vegetable lunch costs 550 yen. Both have the same amount of rice. If you wish to order, write your name and choice on the sheet at reception by noon on Thursday. Pay when collecting your lunch on Friday. Changes are accepted only on Thursday morning. Drinks are not included, so bring your own if needed.', [
    { prompt: '注文したい人は、どうすればいいですか。', answer: '木曜日の正午までに、受付の紙に名前と種類を書く。', reason: 'The notice specifies both the deadline and the paper at reception.', wrong: [['金曜日の朝、店に電話する。', 'The order goes through reception by Thursday noon, not a Friday call to the shop.'], ['木曜日の午後、受付で代金を払う。', 'Payment is on Friday when collecting the lunch; Thursday afternoon is also after the order deadline.'], ['金曜日に、いつもの店へ買いに行く。', 'The usual shop is closed and orders are being placed with a different shop.']], evidence: '木曜日の正午までに受付の紙に名前と種類を書いてください。' },
    { prompt: '二種類のお弁当について、正しいものはどれですか。', answer: 'ご飯の量は同じだが、値段は違う。', reason: 'The prices differ by fifty yen, while the notice explicitly says the rice quantities are the same.', wrong: [['値段は同じだが、ご飯の量は違う。', 'Both parts are reversed: the prices differ and the rice amounts are equal.'], ['野菜のお弁当のほうが高い。', 'The vegetable lunch is 550 yen, less than the 600-yen meat lunch.'], ['どちらにも飲み物が付いている。', 'The notice states that drinks are not included.']], evidence: '肉のお弁当は六百円、野菜のお弁当は五百五十円です。どちらもご飯の量は同じです。' },
    { prompt: 'お弁当の代金は、いつ払いますか。', answer: '金曜日にお弁当を受け取るとき。', reason: 'Payment is due on collection on Friday.', wrong: [['名前を書くとき。', 'The order sheet is used before collection; payment is not due then.'], ['木曜日の正午まで。', 'Noon on Thursday is the order deadline, not the payment time.'], ['金曜日に食べ終わってから。', 'Payment is specified at collection, before eating.']], evidence: '代金は金曜日にお弁当を受け取るときに払います。' },
  ]);

read('rx-message', 'Checking a message before replying', 'email', 'communication', 'reading-short',
  '山田さんへ\n昨日送った会議の案内に、日付の間違いがありました。会議は六月十二日ではなく、六月十九日です。開始時間と場所は変わりません。古い案内は消して、新しい案内だけを保存してください。参加できるかどうかの返事は、今週の金曜日までにお願いします。昨日すでに返事をくださった方も、新しい日付を確認して、もう一度お返事ください。メールが届いたことを伝えるだけの返事は必要ありません。',
  'Dear Yamada, there was an incorrect date in yesterday’s meeting invitation. The meeting is on June 19, not June 12. The start time and location are unchanged. Please delete the old invitation and keep only the new one. Please reply by this Friday to say whether you can attend. Even those who already replied yesterday should check the new date and reply again. You do not need to send a separate reply merely to acknowledge receipt of this email.', [
    { prompt: '昨日の案内から、何が変わりましたか。', answer: '会議の日付。', reason: 'The correction changes June 12 to June 19; the time and place are explicitly unchanged.', wrong: [['会議を始める時間。', 'The email says the start time does not change.'], ['会議を行う場所。', 'The location is unchanged.'], ['返事を送る方法。', 'No change of reply method is described; the stated correction concerns the date.']], evidence: '会議は六月十二日ではなく、六月十九日です。開始時間と場所は変わりません。' },
    { prompt: '昨日、参加すると返事をした人は、どうすればいいですか。', answer: '新しい日付を確かめて、もう一度返事をする。', reason: 'Previously responding people are expressly asked to check the new date and respond again.', wrong: [['何もしなくていい。', 'The email explicitly requires another reply even from those who replied yesterday.'], ['メールが届いたことだけを伝える。', 'A receipt-only acknowledgment is unnecessary and does not confirm attendance.'], ['六月十二日に会場へ行く。', 'June 12 is the incorrect date; the actual meeting is June 19.']], evidence: '昨日すでに返事をくださった方も、新しい日付を確認して、もう一度お返事ください。' },
    { prompt: '金曜日までに伝える必要があることは何ですか。', answer: '新しい日付の会議に参加できるかどうか。', reason: 'The requested reply concerns attendance on the corrected meeting date.', wrong: [['メールを受け取ったかどうかだけ。', 'The email says a simple receipt acknowledgment is not needed.'], ['古い案内を何時に消したか。', 'Deleting the old notice is required, but reporting its deletion time is not.'], ['会場まで何分かかるか。', 'Travel time is not requested.']], evidence: '参加できるかどうかの返事は、今週の金曜日までにお願いします。' },
  ]);

read('rx-neighbor', 'Learning a neighbor’s name', 'article', 'people', 'reading-medium',
  '引っ越したばかりのころ、私は同じ階の人に会っても、名前が分からず、あいさつだけしていた。ある日、エレベーターで会った人が、私の持っていた花を見て「きれいですね」と話しかけてくれた。花を育てるのが好きだと答えると、その人も同じ趣味だと分かった。\n翌週、廊下で会ったとき、私は思い切って名前を聞いた。名前を知ってからは、顔を見かけると自然に声をかけられるようになった。今では、旅行に行くとき、互いに鉢植えの水やりを頼むこともある。\n長い話をしなければ仲良くなれないと思っていたが、そうではなかった。大切なのは、相手が答えやすい話題を一つ見つけて、少しずつ会話を続けることだと思う。無理に個人的なことを聞く必要はない。花の話が、私たちの小さなきっかけになった。',
  'When I had just moved in, I did not know the names of the other people on my floor, so I only greeted them. One day, someone I met in the elevator saw the flowers I was carrying and said they were beautiful. When I replied that I liked growing flowers, I learned that we shared the hobby. The next week, when we met in the corridor, I gathered the courage to ask their name. Once I knew it, I found it natural to speak when I saw them. Now we sometimes ask each other to water our potted plants while traveling. I used to think that becoming friends required long conversations, but that was not so. I think what matters is finding one easy topic for the other person to answer and continuing to talk little by little. There is no need to force personal questions. Talking about flowers gave us a small beginning.', [
    { prompt: '二人が話すようになったきっかけは何ですか。', answer: 'エレベーターで花について話したこと。', reason: 'The first conversation begins when the neighbor comments on the flowers in the elevator.', wrong: [['同じ日に引っ越したこと。', 'The passage does not say they moved on the same day.'], ['名前を忘れて謝ったこと。', 'The writer had not known the name; there is no incident of forgetting it and apologizing.'], ['旅行で同じ町へ行ったこと。', 'Trips explain later plant-watering help, not their first conversation.']], evidence: '私の持っていた花を見て「きれいですね」と話しかけてくれた。' },
    { prompt: '名前を知った後、筆者にはどんな変化がありましたか。', answer: '相手を見かけたとき、声をかけやすくなった。', reason: 'Knowing the name made it natural for the writer to speak when they saw the neighbor.', wrong: [['花を育てるのをやめた。', 'They continue sharing the hobby and helping with potted plants.'], ['毎日、長い話をするようになった。', 'The writer says long conversations are unnecessary; daily lengthy talks are not described.'], ['旅行へ行かなくなった。', 'Travel is still mentioned as the occasion for exchanging watering favors.']], evidence: '名前を知ってからは、顔を見かけると自然に声をかけられるようになった。' },
    { prompt: '筆者が、人と仲良くなるために大切だと考えていることは何ですか。', answer: '答えやすい話題から、少しずつ会話を続けること。', reason: 'The writer explicitly identifies an easy topic and gradual continuing conversation as important.', wrong: [['初めから個人的なことをたくさん聞くこと。', 'The passage says there is no need to force personal questions.'], ['一度にできるだけ長く話すこと。', 'The writer rejects the belief that long conversations are required.'], ['同じ趣味の人とだけあいさつすること。', 'The passage gives a shared hobby as one opening, not a rule to greet only those people.']], evidence: '相手が答えやすい話題を一つ見つけて、少しずつ会話を続けること' },
  ]);

read('rx-handover', 'Leaving useful notes for the next shift', 'email', 'work', 'reading-medium',
  '店の皆さんへ\n来週から、仕事が終わる前に、その日の様子を記録するノートを使うことになりました。今までは、次の担当者に口で伝えていましたが、忙しい時間には説明する余裕がなく、大切な情報が伝わらないことがありました。\nノートには、まだ終わっていない仕事と、お客様から受けた特別な注文を書いてください。終わった仕事を全部書く必要はありません。商品の数は別の表で確認できるので、ここには書かなくて大丈夫です。読む人がすぐ理解できるように、一つの内容を短い文で書きましょう。\n次の担当者は、仕事を始める前にノートを読んでください。分からないことがあれば、書いた人に確認してください。記録しただけで伝わったと思わず、重要な変更は直接伝えることも続けます。まず二週間使ってみて、書く内容が多すぎるかどうか、皆さんの意見を聞く予定です。\n店長',
  'To all staff: starting next week, we will use a notebook to record the day’s situation before finishing work. Until now we have passed information to the next person verbally, but at busy times there has not been enough time to explain, and important information has sometimes not reached them. Write unfinished jobs and special customer orders in the notebook. There is no need to list all completed work. Product quantities can be checked on a separate sheet, so they need not be written here. Use a short sentence for each item so readers can understand quickly. The next person should read the notebook before starting work and ask the writer about anything unclear. We will continue conveying important changes directly, rather than assuming a written record was understood. After trying it for two weeks, we plan to ask whether there is too much to write. Manager.', [
    { prompt: 'このノートを使うことになった理由は何ですか。', answer: '忙しいとき、口だけでは大切な情報を伝えられないことがあるから。', reason: 'The manager explains that verbal handovers sometimes failed at busy times.', wrong: [['商品の数を数える表がなくなったから。', 'A separate stock-count sheet still exists and is explicitly mentioned.'], ['終わった仕事の量を毎日比べたいから。', 'Staff are told not to record every completed task.'], ['お客様にノートを見せたいから。', 'The notebook is for staff handovers; showing it to customers is not proposed.']], evidence: '忙しい時間には説明する余裕がなく、大切な情報が伝わらないことがありました。' },
    { prompt: 'ノートに書く必要があるのは、どれですか。', answer: 'まだ終わっていない仕事。', reason: 'Unfinished jobs are specifically listed as required notebook contents.', wrong: [['その日に終わった仕事全部。', 'The manager explicitly says completed work need not all be written.'], ['商品の数全部。', 'Product quantities are checked on a separate sheet.'], ['二週間後の全員の予定。', 'Two weeks is the trial length; staff schedules are not requested.']], evidence: 'まだ終わっていない仕事と、お客様から受けた特別な注文を書いてください。' },
    { prompt: '次の担当者は、ノートの内容が分からないとき、どうしますか。', answer: 'それを書いた人に確認する。', reason: 'The instruction is to ask the writer about unclear items.', wrong: [['その部分を消す。', 'Nothing authorizes deleting information that is unclear.'], ['お客様に必ず質問する。', 'The specified person to ask is the writer, not a customer.'], ['二週間後まで何もしない。', 'Two weeks is the review point for the system, not a waiting period for questions.']], evidence: '分からないことがあれば、書いた人に確認してください。' },
  ]);

read('rx-studygroup', 'Changing a study group', 'article', 'education', 'reading-medium',
  '私たちの日本語の勉強会では、以前、一人ずつ長い文章を読んで、その後で分からない言葉を調べていた。ところが、読むのが速い人は待つ時間が長く、ゆっくり読む人は周りに合わせようとして、内容を十分に理解できなかった。\nそこで、今は三人ずつの小さいグループに分かれ、短い文章を使っている。最初にそれぞれが黙って読み、その後、内容を自分の言葉で説明する。知らない言葉があっても、すぐに辞書を開かず、前後の文から意味を考えるようにした。\nこの方法に変えてから、質問する人が増えた。文章を読んだだけでは気づかなかった点も、人に説明すると、自分が理解していないことが分かる。速く読む練習にはならないかもしれないが、内容を確かめるには役立っている。これからも、ときどき全員で集まり、グループで見つけた疑問を共有したい。',
  'In our Japanese study group, we used to take turns reading a long passage and then look up unfamiliar words. Faster readers had long waits, while slower readers tried to keep up and could not fully understand the content. We now work in groups of three with short passages. First everyone reads silently, then explains the content in their own words. Even with an unfamiliar word, we try to infer its meaning from surrounding sentences rather than immediately opening a dictionary. Since changing methods, more people ask questions. Explaining to others also reveals things we had not realized we did not understand just by reading. It may not train reading speed, but it helps check comprehension. We would like to continue occasionally meeting as a whole group to share questions found in the small groups.', [
    { prompt: '以前の勉強会で、ゆっくり読む人はどんな問題がありましたか。', answer: '周りに合わせようとして、内容をよく理解できなかった。', reason: 'Slower readers tried to match the others and lost comprehension.', wrong: [['読む順番が一度も来なかった。', 'They took turns reading; the problem was understanding while trying to keep pace.'], ['辞書を持っていなかった。', 'Lack of dictionaries is not identified as the problem.'], ['短い文章しか読めなかった。', 'The previous method used long texts for everyone.']], evidence: '周りに合わせようとして、内容を十分に理解できなかった。' },
    { prompt: '今の勉強会では、知らない言葉があったら、まず何をしますか。', answer: '前後の文を見て、意味を考える。', reason: 'They first infer meaning from the surrounding context.', wrong: [['すぐに辞書で調べる。', 'The new method explicitly avoids immediately opening a dictionary.'], ['必ず読むのをやめる。', 'Unfamiliar vocabulary is used for inference, not a reason to stop.'], ['先生に文章を全部訳してもらう。', 'The passage describes group work and self-explanation, not full translation by a teacher.']], evidence: '前後の文から意味を考えるようにした。' },
    { prompt: '筆者は、今の方法のどんな点を評価していますか。', answer: '自分がどのくらい内容を理解しているか確かめられる点。', reason: 'Explaining the text reveals gaps in understanding and helps check comprehension.', wrong: [['誰よりも速く読めるようになる点。', 'The writer says the method may not train reading speed.'], ['質問をしなくてもよくなる点。', 'Questions have increased and are welcomed.'], ['長い文章だけを使う点。', 'The new method uses short passages.']], evidence: '内容を確かめるには役立っている。' },
  ]);

read('rx-river', 'Watching the river through the seasons', 'article', 'nature', 'reading-medium',
  '近所の川には、春になると白い鳥が集まる。私は毎年同じ場所で写真を撮っていたが、今年は鳥の数が少ないように感じた。川が汚れたせいかと思い、地域で自然を調べている人に聞いてみた。\nその人によると、数日間の観察だけで、鳥が減ったと決めるのは早いそうだ。雨の量や気温によって、鳥が来る時期や場所が変わることもあるという。去年の写真を見直すと、撮った日は今年より二週間ほど遅かった。私は違う時期の写真を比べていたのだ。\nそれからは、写真だけでなく、日付、天気、見た鳥の数をメモするようにした。一度見ただけでは気づかない変化も、記録を続けると分かるかもしれない。川がきれいかどうかも気になるが、鳥が少ないという印象だけで原因を決めないようにしたい。来月も同じ場所へ行って、観察を続けるつもりだ。',
  'White birds gather at the nearby river in spring. I photographed them at the same place every year, but this year I felt there were fewer. Wondering whether the river had become dirty, I asked someone who studies local nature. They said it was too soon to conclude from only a few days of observation that the birds had decreased. Rainfall and temperature can change when and where birds arrive. Looking at last year’s photos, I discovered that I had taken them about two weeks later than this year’s. I had been comparing different times of the season. Since then I have recorded dates, weather, and bird numbers, as well as taking photographs. Continued records might reveal changes missed in one visit. I am concerned about the river’s cleanliness too, but do not want to decide the cause merely from an impression of fewer birds. I plan to visit the same place next month and keep observing.', [
    { prompt: '去年と今年の写真を比べるとき、筆者は何を見落としていましたか。', answer: '写真を撮った時期が違うこと。', reason: 'The older photographs were taken roughly two weeks later in the season.', wrong: [['写真を撮った川が違うこと。', 'The writer took photographs at the same location each year.'], ['白い鳥ではなかったこと。', 'The account concerns white birds throughout.'], ['去年は写真を撮らなかったこと。', 'Last year’s photos exist and are checked again.']], evidence: '撮った日は今年より二週間ほど遅かった。' },
    { prompt: '自然を調べている人は、何と言いましたか。', answer: '短い期間だけ見て、鳥が減ったと決めるべきではない。', reason: 'A few days are not enough to conclude that the population has fallen.', wrong: [['鳥の数は天気に関係なく同じだ。', 'They explain that rainfall and temperature can affect arrival timing and location.'], ['川が汚れたことが原因に違いない。', 'The writer’s initial suspicion is not confirmed.'], ['写真を撮れば、観察を続ける必要はない。', 'The discussion leads to continued observation and dated records.']], evidence: '数日間の観察だけで、鳥が減ったと決めるのは早い' },
    { prompt: '筆者は今、写真のほかに何を記録していますか。', answer: '日付、天気、鳥の数。', reason: 'These are the three details the writer now records.', wrong: [['川の深さと水の温度だけ。', 'Depth and water temperature are not listed in the new records.'], ['近所の人の名前と住所。', 'The records concern observations, not residents’ personal information.'], ['去年の旅行の費用。', 'Travel expenses are unrelated to the river observations.']], evidence: '日付、天気、見た鳥の数をメモするようにした。' },
  ]);

read('rx-asking', 'Finding the courage to ask', 'article', 'feelings', 'reading-long',
  '新しい職場に入ったとき、私は分からないことがあっても、なかなか質問できなかった。周りの人は忙しそうだったし、同じことを何度も聞いたら、仕事ができない人だと思われるのではないかと心配していた。そのため、資料を一人で読み直して、時間をかけて調べることが多かった。\nある日、頼まれた表を作るのに二時間もかかった。ようやく完成したと思ったら、使う資料の種類を間違えていた。先輩に事情を話すと、「最初に確認してくれれば、すぐ説明できたよ」と言われた。自分で解決しようとしたことが、かえって仕事を遅くしていたのだ。\n次の日から、質問したいことを短くメモして、まず「今、少しよろしいですか」と声をかけるようにした。忙しいと言われたら、何時なら話せるか聞く。説明を聞いた後は、自分の理解が合っているか、もう一度内容を簡単に言って確かめることにした。\nすると、先輩は「どこまで分かっているか分かるから、答えやすい」と言ってくれた。質問する前に何も考えないのではなく、自分で調べたことと、まだ分からないことを分けて伝えるのが大切だった。今でも声をかけるときは少し緊張する。でも、分からないまま進めるより、相手の都合を確かめて質問するほうが、お互いの時間を大切にできると感じている。',
  'When I joined a new workplace, I found it difficult to ask questions even when I did not understand. Everyone looked busy, and I worried that repeatedly asking the same thing would make them think I could not do the job. I often reread materials and spent time researching alone. One day, a table I had been asked to make took two hours. Just when I thought it was finished, I learned I had used the wrong kind of material. When I explained to a senior colleague, they said they could have explained quickly if I had checked at the start. Trying to solve it alone had delayed the work instead. From the next day, I briefly noted my questions and first asked whether they had a moment. If they were busy, I asked what time would work. After an explanation, I briefly restated it to check my understanding. The colleague said it made questions easier to answer because they could see how much I understood. What mattered was not asking without thinking, but distinguishing what I had researched from what I still did not understand. I still feel a little nervous speaking up. However, I now feel that checking availability and asking respects both people’s time more than proceeding without understanding.', [
    { prompt: '筆者は、最初、なぜ質問できなかったのですか。', answer: '周りの人が忙しそうで、自分の能力を悪く思われるのも心配だったから。', reason: 'The introduction names both others’ apparent busyness and concern about seeming incapable.', wrong: [['資料を読むことが禁止されていたから。', 'The writer was reading the materials repeatedly, not forbidden from reading them.'], ['先輩が質問には絶対答えないと言ったから。', 'The colleague later says an early question could have been answered quickly.'], ['仕事の内容を全部理解していたから。', 'The writer explicitly had things they did not understand.']], evidence: '周りの人は忙しそうだったし、同じことを何度も聞いたら、仕事ができない人だと思われるのではないかと心配していた。' },
    { prompt: '表を作ったときの経験から、筆者は何に気づきましたか。', answer: '一人で解決しようとしたことで、仕事がかえって遅くなった。', reason: 'The writer spent two hours on the wrong source and explicitly recognizes that working alone delayed the task.', wrong: [['二時間あれば、どんな表でも正しく作れる。', 'The table was wrong despite taking two hours.'], ['資料は使わずに仕事をしたほうがよい。', 'The problem was choosing the wrong source, not using materials at all.'], ['先輩に相談すると、必ず作業が遅くなる。', 'The colleague could have explained quickly; consulting earlier would have helped.']], evidence: '自分で解決しようとしたことが、かえって仕事を遅くしていたのだ。' },
    { prompt: '筆者が今、大切だと思っている質問の仕方はどれですか。', answer: '相手の都合を確かめ、調べたことと分からないことを分けて伝える。', reason: 'The revised approach combines checking availability with distinguishing researched and unresolved points.', wrong: [['相手が忙しくても、すぐ長い説明を求める。', 'The writer first asks whether the person is available and can arrange another time.'], ['何も調べず、同じ質問を何度もする。', 'The writer explicitly distinguishes this from asking without thinking.'], ['理解できなくても、分かったと言って作業を進める。', 'They restate explanations to confirm understanding rather than proceed without it.']], evidence: '自分で調べたことと、まだ分からないことを分けて伝えるのが大切だった。' },
  ]);

read('rx-phone', 'Deciding how to use notifications', 'article', 'technology', 'reading-long',
  'スマートフォンを使い始めたころ、私は新しい知らせが届くと、すぐに画面を見ていた。友達からの連絡を早く読めるのは便利だったが、料理の途中や本を読んでいるときにも手を止めるようになった。何をしようとしていたか忘れてしまい、同じページを何度も読むこともあった。\nある休日、思い切って知らせの音を全部消してみた。すると、作業に集中できた一方で、家族からの大切な電話にも気づかなかった。電話をかけ直したとき、家族は私が急に具合を悪くしたのではないかと心配していた。何でも消せばよいわけではないと思った。\nそこで、使っているアプリを一つずつ見直した。家族からの電話は音が鳴るようにして、それ以外の知らせは画面に出るだけにした。仕事の連絡は、昼休みと仕事が終わった後にまとめて確認する。急ぎの場合は電話してほしいと、同僚にも伝えた。\nこの方法にしてから、画面を開く回数が減った。連絡を読まないのではなく、いつ読むかを自分で決められるようになったのである。もちろん、予定が変われば、確認する時間も変える必要がある。便利な機能をそのまま使い続けるのではなく、自分の生活に合っているか、ときどき考えることが大切だと思う。新しいアプリを入れたときも、最初に知らせ方を確認するようにしている。',
  'When I began using a smartphone, I immediately checked the screen whenever a notification arrived. Quickly reading friends’ messages was convenient, but I started interrupting cooking and reading as well. I sometimes forgot what I had intended to do and reread the same page. One day off, I tried silencing every notification. It helped me concentrate, but I also missed an important family call. When I called back, my family said they had worried I might suddenly have become ill. I realized silencing everything was not the answer. I reviewed each app. Family calls still ring, while other notifications only appear on screen. I check work messages together during lunch and after work, and told colleagues to call if something is urgent. Since changing this, I open the screen less often. Rather than refusing to read messages, I can decide when to read them. Of course, changed plans may require changed checking times. I think it matters to occasionally consider whether a convenient feature suits one’s life instead of leaving it unchanged. When installing a new app, I now check its notification settings first.', [
    { prompt: '知らせの音を全部消したとき、どんな問題が起こりましたか。', answer: '家族からの大切な電話に気づかなかった。', reason: 'The complete silence caused the writer to miss an important family call.', wrong: [['本に集中できなくなった。', 'Silencing notifications improved concentration; the difficulty was missing the call.'], ['アプリを使えなくなった。', 'The apps remained usable; only notification sounds had been changed.'], ['友達の住所を全部消してしまった。', 'No contacts or addresses were deleted.']], evidence: '家族からの大切な電話にも気づかなかった。' },
    { prompt: '今、仕事で急ぎの連絡をしたい同僚は、どうすればいいですか。', answer: '電話をする。', reason: 'The writer specifically asked colleagues to call for urgent matters.', wrong: [['昼休みまで必ず待つ。', 'Lunch is a regular message-checking time; urgent matters should be phoned.'], ['同じアプリの知らせを何度も送る。', 'Repeated app notifications are not the agreed urgent-contact method.'], ['家族にだけ伝える。', 'Family calls remain audible, but work colleagues are told to call directly.']], evidence: '急ぎの場合は電話してほしいと、同僚にも伝えた。' },
    { prompt: 'この文章で、筆者が最も伝えたいことは何ですか。', answer: '便利な機能も、自分の生活に合うか見直すとよい。', reason: 'The conclusion calls for checking whether features fit one’s life and illustrates customized notification settings.', wrong: [['スマートフォンの連絡は全部読まないほうがよい。', 'The writer continues reading messages at chosen times and preserves urgent calls.'], ['便利な機能は、初めの設定のまま使うべきだ。', 'The writer explicitly argues for reconsidering settings.'], ['新しいアプリを入れることだけが大切だ。', 'The final example concerns checking notification behavior, not installing more apps.']], evidence: '自分の生活に合っているか、ときどき考えることが大切だと思う。' },
  ]);

read('rx-craft', 'What a craft workshop taught me', 'article', 'culture', 'reading-long',
  '市民センターで、地域に昔から伝わる紙の飾りを作る教室が開かれた。私は細かい作業が苦手だったが、完成した飾りの写真がきれいだったので、参加してみることにした。教室には、子どもから年配の人まで、いろいろな人が集まっていた。\n初めに先生が作り方を見せてくれた。私は写真と同じ形にしようとして、折る場所を何度も測った。しかし、紙が少しずれてしまい、思ったようにできなかった。隣の人は、私より早く作り終えて、色の組み合わせを楽しんでいた。自分だけ遅れているようで、少し落ち着かなかった。\nその様子を見た先生は、「基本の折り方を覚えたら、あとは好きな色や形を試していいんですよ」と言った。そして、昔の飾りも、作った人によって少しずつ違っていたことを教えてくれた。同じ物を正確に作ることだけが目的ではなかったのだ。\n私は写真を見るのをやめ、家の窓に合いそうな色を選んで作り直した。完成した物は見本とは違ったが、自分で選んだ色が入っていて、前より気に入った。帰りに、同じグループの人たちと作品を見せ合うと、それぞれの考え方が分かって面白かった。\n伝統的な物を学ぶことは、ただ昔と同じ物を作ることではないと思う。基本を知った上で、自分の暮らしにどう取り入れるか考えることも、その文化に親しむ方法なのだと感じた。',
  'The civic center held a class in making paper decorations traditionally made in the area. I was not good at detailed work, but photographs of the finished decorations were beautiful, so I decided to try. People of many ages, from children to older adults, attended. First the teacher demonstrated the method. Trying to match the photograph, I repeatedly measured the folding positions, but the paper shifted slightly and did not turn out as I intended. The person beside me finished sooner and was enjoying combinations of colors. I felt uneasy, as though I alone was behind. Seeing this, the teacher said that once we learned the basic folds we could try colors and shapes we liked, and explained that older decorations also differed somewhat by maker. Producing an exact copy was not the only aim. I stopped looking at the photo and remade mine in colors that would suit my window. It differed from the sample, but I liked it more because of my chosen colors. Sharing work with group members afterward was interesting because it revealed different ways of thinking. I feel learning a traditional craft need not mean only reproducing the past. Knowing the basics and considering how to incorporate them into our lives is another way to become familiar with the culture.', [
    { prompt: '筆者は初め、どのように飾りを作ろうとしていましたか。', answer: '写真と同じ形になるように、折る場所を何度も測っていた。', reason: 'The writer initially tried to reproduce the photograph precisely by measuring fold positions.', wrong: [['好きな色を自由に組み合わせていた。', 'Enjoying colors initially describes the neighbor; the writer does this only after the teacher’s advice.'], ['折り方を習わず、すぐに作り始めた。', 'The teacher demonstrated the method before the writer worked.'], ['隣の人の作品を買おうとしていた。', 'The passage describes making one’s own work, not purchasing another participant’s work.']], evidence: '写真と同じ形にしようとして、折る場所を何度も測った。' },
    { prompt: '先生の説明を聞いて、筆者は何が分かりましたか。', answer: '基本を覚えれば、見本と違う色や形を試してもよい。', reason: 'The teacher explicitly permits individual experimentation after the basic folds are learned.', wrong: [['昔の飾りは全部同じ形だった。', 'The teacher says historical decorations also differed by maker.'], ['完成する速さだけで作品を評価する。', 'Speed caused the writer’s anxiety, but it is not the teacher’s stated standard.'], ['作り方を学ぶ必要はまったくない。', 'The advice begins with learning the basic folds.']], evidence: '基本の折り方を覚えたら、あとは好きな色や形を試していいんですよ' },
    { prompt: '筆者は、文化に親しむ方法として、何を挙げていますか。', answer: '基本を知って、自分の生活に取り入れる方法を考えること。', reason: 'The final paragraph connects cultural familiarity with adapting known basics to one’s life.', wrong: [['昔の物を同じ形で作ることだけ。', 'The writer says reproducing the past is not the only meaning of learning.'], ['見本を一度も見ないこと。', 'The writer learned from a demonstration and initially used a sample; avoiding all examples is not proposed.'], ['自分の作品を人に見せないこと。', 'Sharing completed works is described positively.']], evidence: '基本を知った上で、自分の暮らしにどう取り入れるか考えることも、その文化に親しむ方法' },
  ]);

read('rx-buffer', 'Leaving space in a busy day', 'article', 'time', 'reading-long',
  '私は予定を立てるのが好きで、休日にも、何時に何をするか細かく決めていた。買い物を三十分で済ませ、その後、友達に会い、夕方には家の掃除をするというように、一日の予定を全部埋めると、時間を上手に使えている気がした。\nところが、予定どおりに進む日は少なかった。店で探していた物が見つからなかったり、友達との話が長くなったりすると、その後の予定まで遅れてしまう。楽しい休日のはずなのに、時計を見るたびに、まだ終わっていないことが気になっていた。\nあるとき、友達に相談すると、「予定と予定の間に、何もしなくていい時間を入れてみたら」と言われた。初めは、使わない時間を作るのはもったいないと思った。それでも、次の休日は、外出から帰った後に一時間、予定を入れないことにした。\nその日は電車が遅れたが、帰宅後に余裕があったので、掃除を急がずに済んだ。もし早く帰れたら、その時間は休んだり、やりたいことを選んだりすればいい。予定を決めない時間にも、役割があることが分かった。\n今は、必ずしたいことを二つか三つ選び、それ以外は時間があればすることにしている。予定が減ったからといって、何もできなくなったわけではない。むしろ、一つのことに落ち着いて取り組めるようになった。予定を守ることだけを目標にせず、変更できる余裕も残しておきたいと思っている。',
  'I like planning and used to decide in detail what to do at each time even on days off. Filling my day with tasks—thirty minutes of shopping, then meeting a friend, then cleaning in the evening—made me feel I was using time well. Yet few days went as planned. If I could not find something in a shop or a conversation lasted longer, subsequent plans were delayed. On what should have been a pleasant day off, every look at the clock reminded me of unfinished tasks. When I consulted a friend, they suggested leaving periods between plans when I did not have to do anything. At first unused time felt wasteful. Still, the next day off, I left one hour after returning home unplanned. The train was late, but the spare time meant I did not have to rush cleaning. If I got home early, I could rest or choose something I wanted to do. I realized unplanned time has a role too. I now choose two or three things I definitely want to do, and do the rest if there is time. Fewer plans do not mean achieving nothing; instead, I can approach each task calmly. I want to leave room for changes instead of making keeping the schedule my only goal.', [
    { prompt: '以前、筆者が時計を見るたびに気になっていたことは何ですか。', answer: '予定したことが、まだ終わっていないこと。', reason: 'When plans slipped, the clock reminded the writer of unfinished tasks.', wrong: [['時計が壊れていること。', 'The clock is not described as faulty.'], ['友達に会う予定が一つもないこと。', 'Meeting a friend was part of the busy schedule.'], ['休日に何をしたか全部忘れること。', 'The worry was unfinished plans, not forgetting completed activities.']], evidence: 'まだ終わっていないことが気になっていた。' },
    { prompt: '予定を入れない一時間が、その日に役立ったのはなぜですか。', answer: '電車が遅れても、その後の掃除を急がずに済んだから。', reason: 'The spare hour absorbed the train delay and kept cleaning from becoming rushed.', wrong: [['電車の時間を早く変えられたから。', 'The writer could not control the train; they changed their own schedule.'], ['掃除をする必要がなくなったから。', 'Cleaning still happened, but without rushing.'], ['友達との約束を忘れてよくなったから。', 'The friend’s suggestion concerns buffer time, not disregarding appointments.']], evidence: 'その日は電車が遅れたが、帰宅後に余裕があったので、掃除を急がずに済んだ。' },
    { prompt: '筆者は今、どのように予定を立てていますか。', answer: '必ずしたいことを少し選び、残りは時間があればする。', reason: 'The current method chooses two or three priorities and treats other tasks as optional if time permits.', wrong: [['一日の時間を全部、細かい予定で埋める。', 'This describes the old approach, which caused stress.'], ['何もしない日を毎週必ず作る。', 'The writer reserves unplanned time but still chooses tasks; no weekly do-nothing rule is stated.'], ['友達の予定だけに合わせる。', 'The writer selects their own priorities rather than following only a friend’s schedule.']], evidence: '必ずしたいことを二つか三つ選び、それ以外は時間があればすることにしている。' },
  ]);

read('rx-bag', 'Bag care and repair services', 'advertisement', 'shopping', 'reading-information',
  '駅前かばん店　お手入れ・修理のご案内\nお気に入りのかばんを長く使いたい方へ。汚れを落とすサービスと、持ち手やファスナーの修理を行っています。まず実物を見て、できる作業と費用を説明します。見積もりを聞いてから、頼むかどうか決めていただけます。\n【簡単なお手入れ】\n受付：月・火・木・金・土・日、午前十時～午後四時\n予約：不要\n料金：布のかばん一つ八百円。革のかばんは対象外です。\n受け取り：通常は受付から一時間後。混んでいる場合は先にお知らせします。\n【持ち手・ファスナーの修理】\n受付：月・火・木・金、午前十時～午後五時\n予約：必要。前日の午後五時までに電話してください。\n料金：持ち手の修理は千五百円から。ファスナーは状態を見て金額を決めます。\n受け取り：三日後以降。材料によっては一週間ほどかかる場合があります。\n【無料相談】\n受付：土・日の午後一時～三時\n予約：不要。修理できるか相談するだけなら無料ですが、その場では修理しません。\n水曜日は定休日です。どのサービスも、かばんを持ってご来店ください。写真だけでは受付できません。修理した部分には三か月の保証が付きます。保証の内容は受け取り時の紙で確認してください。代金は受け取りの際に、現金かカードでお支払いください。電話での相談はできますが、作業の申し込みは店で行います。',
  'Station-front Bag Shop: care and repair services. If you want to keep using a favorite bag, we offer cleaning and repairs to handles and zippers. We first examine the actual bag and explain possible work and costs. You can decide after hearing the estimate. Simple care: accepted on Monday, Tuesday, Thursday, Friday, Saturday, and Sunday, 10 a.m.–4 p.m.; no booking; 800 yen per fabric bag, excluding leather bags. Collection is usually one hour after acceptance; you will be told beforehand if we are busy. Handle and zipper repairs: accepted Monday, Tuesday, Thursday, and Friday, 10 a.m.–5 p.m.; booking required by phone by 5 p.m. the previous day. Handle repairs start at 1,500 yen; zipper prices depend on inspection. Collection is three days later or beyond; materials may take about a week. Free consultation: Saturday and Sunday, 1–3 p.m.; no booking. Asking whether repair is possible is free, but repairs are not done on the spot. Closed Wednesdays. Bring the bag for every service; photos alone are not accepted. Repaired parts have a three-month guarantee; check the collection paper for details. Pay on collection with cash or card. Telephone consultation is available, but work requests must be made at the shop.', [
    { prompt: '土曜日の午前中に、予約なしで布のかばんの汚れを落としてもらいたい人は、どのサービスを利用できますか。', answer: '簡単なお手入れ。', reason: 'Simple care accepts fabric bags without reservations on Saturday starting at ten.', wrong: [['持ち手・ファスナーの修理。', 'Repairs require reservations and are accepted only on the specified weekdays.'], ['午後の無料相談だけ。', 'Consultation is in the afternoon and does not perform cleaning.'], ['写真を電話で送るサービス。', 'All services require the actual bag; a photo-only service is not offered.']], evidence: '受付：月・火・木・金・土・日、午前十時～午後四時\n予約：不要\n料金：布のかばん一つ八百円。' },
    { prompt: '持ち手の修理を頼む人は、どうすればいいですか。', answer: '前日の午後五時までに電話で予約し、かばんを店に持っていく。', reason: 'Repairs need a phone reservation by the previous day’s deadline and the actual bag at the shop.', wrong: [['水曜日に、写真だけを送る。', 'Wednesday is closed, and photos alone are not accepted.'], ['土曜日の午前中に予約なしで行く。', 'The repair service is weekday-only and requires booking.'], ['電話をすれば、その日の一時間後に必ず受け取れる。', 'One hour applies to simple care; repairs take at least three days.']], evidence: '予約：必要。前日の午後五時までに電話してください。' },
    { prompt: '無料相談について、正しいものはどれですか。', answer: '修理できるか聞けるが、その場で修理はしてもらえない。', reason: 'The consultation is free for assessing feasibility but expressly excludes on-the-spot repair.', wrong: [['どんな修理も無料でしてもらえる。', 'Only consultation is free, not the repair itself.'], ['必ず前日までの予約が必要だ。', 'The free-consultation section says reservations are unnecessary.'], ['毎週水曜日の午後に行っている。', 'It is held on Saturday and Sunday afternoons; Wednesday is closed.']], evidence: '修理できるか相談するだけなら無料ですが、その場では修理しません。' },
  ]);

read('rx-trips', 'Choose a one-day outing', 'advertisement', 'travel', 'reading-information',
  'ひかり旅行社　日帰りの小さな旅\n忙しくても、少し違う一日を過ごしてみませんか。三つのコースは、どれも駅の北口で集合します。料金には移動のバス代と見学する場所の入場料が含まれます。昼食はコースによって異なりますので、下の案内をご確認ください。\nＡ　海の町と市場\n毎週土曜日、午前九時集合・午後四時帰着。料金四千円。市場の買い物と海辺の散歩を楽しみます。昼食代は含まれません。少しの雨なら実施しますが、風が強い日は中止します。\nＢ　山の公園\n毎週日曜日、午前十時集合・午後五時帰着。料金五千円。公園では二時間ほど歩きます。弁当付き。雨の場合は中止します。歩きやすい靴でご参加ください。\nＣ　町の歴史と工芸館\n毎週金曜日、午前九時半集合・午後三時半帰着。料金三千五百円。見学場所はすべて屋内なので、雨でも実施します。昼食は各自で用意するか、館内の食堂をご利用ください。\n申し込みは、出発の二日前の午後六時まで。電話か店の窓口で受け付けます。定員になったコースは、締め切り前でも受付を終了します。代金は、申し込みの翌日までに店でお支払いください。集合時には支払えません。\n出発前日の正午までに中止を決めた場合は、旅行社から電話でお知らせします。大きな荷物はバスに持ち込めません。貴重品は自分で管理してください。集合場所が分からない方には、申し込み時に地図をお渡しします。',
  'Hikari Travel: small day trips. All three courses meet at the station’s north exit. Prices include bus transportation and attraction admission; lunch arrangements vary. A: seaside town and market, Saturdays, meet 9 a.m., return 4 p.m., 4,000 yen. Shopping at the market and a seaside walk; lunch not included. Runs in light rain but canceled in strong winds. B: mountain park, Sundays, meet 10 a.m., return 5 p.m., 5,000 yen. About two hours of walking, boxed lunch included; canceled in rain. Wear comfortable walking shoes. C: town history and craft museum, Fridays, meet 9:30 a.m., return 3:30 p.m., 3,500 yen. All visits are indoors, so the course runs in rain. Bring lunch or use the museum cafeteria. Apply by 6 p.m. two days before departure, by telephone or at the office. Full courses close applications before the deadline. Pay at the office by the day after applying; payment at the meeting point is unavailable. If cancellation is decided by noon the day before departure, the agency will call. Large luggage is not allowed on the bus. Keep valuables yourself. A meeting-point map is available when applying.', [
    { prompt: '金曜日に休みがあり、雨でも実施するコースを選びたい人には、どれが合いますか。', answer: 'Ｃの町の歴史と工芸館。', reason: 'C is on Fridays and explicitly operates in rain because the visits are indoors.', wrong: [['Ａの海の町と市場。', 'A runs on Saturday, not Friday.'], ['Ｂの山の公園。', 'B runs on Sunday and is canceled in rain.'], ['どのコースも雨の場合は中止するので選べない。', 'C explicitly operates in rainy weather.']], evidence: '毎週金曜日、午前九時半集合・午後三時半帰着。料金三千五百円。見学場所はすべて屋内なので、雨でも実施します。' },
    { prompt: '昼食が料金に含まれているのは、どのコースですか。', answer: 'Ｂの山の公園。', reason: 'B explicitly includes a boxed lunch; A excludes lunch and C requires arranging one independently.', wrong: [['Ａの海の町と市場。', 'A states that lunch costs are not included.'], ['Ｃの町の歴史と工芸館。', 'C participants bring lunch or use the cafeteria themselves.'], ['三つとも含まれている。', 'A and C do not include lunch in the advertised price.']], evidence: '公園では二時間ほど歩きます。弁当付き。' },
    { prompt: '申し込みをした後、代金はいつ、どこで払いますか。', answer: '翌日までに、旅行社の店で払う。', reason: 'The brochure states payment is due at the office by the following day.', wrong: [['出発当日、駅の北口で払う。', 'Payment at the gathering point is expressly unavailable.'], ['旅行から帰った一週間後に払う。', 'This is later than the day-after-application deadline.'], ['申し込みの二日前までに、バスの中で払う。', 'The brochure sets payment after applying and at the office, not on a bus.']], evidence: '代金は、申し込みの翌日までに店でお支払いください。集合時には支払えません。' },
  ]);

read('rx-buses', 'Station buses during roadworks', 'notice', 'transport', 'reading-information',
  '中央駅からのバスをご利用の皆さんへ\n来週の月曜日から金曜日まで、駅前の道路工事に伴い、一部の乗り場と運行時間を変更します。土曜日からは通常の運行に戻る予定です。駅へ戻るバスの時刻は変更しません。以下は、工事期間中に駅から出発するバスの案内です。\n１番　市民病院行き\n乗り場：北口の三番乗り場\n出発：午前八時から午後六時まで、毎時〇分と三十分\n所要時間：約二十分\n変更点：普段の南口一番乗り場は使いません。\n２番　博物館行き\n乗り場：南口の二番乗り場\n出発：午前九時、十時、十一時、午後一時、二時、三時\n所要時間：約三十分\n変更点：正午の便は運休します。その他の時刻と乗り場は変わりません。\n３番　川の公園行き\n乗り場：北口の四番乗り場\n出発：午前九時半、十一時半、午後一時半、三時半\n所要時間：約十五分\n変更点：すべての便を、通常より三十分遅らせます。\n料金はどの路線も二百円です。駅の売店では回数券を販売していますが、現金でも乗れます。大きな荷物を持っている方は、通路をふさがないようにしてください。\n工事期間中は、乗り場の近くに案内係がいます。バス会社への電話がつながりにくい場合は、駅の案内所でも時刻を確認できます。交通状況によって到着が遅れることがあるので、時間に余裕を持ってご利用ください。',
  'To users of buses from Central Station: due to roadworks next Monday through Friday, some stops and departure times will change. Normal operation is expected to resume Saturday. Times of buses returning to the station are unchanged. These are departures from the station during works. Route 1 to the civic hospital: north exit stop 3, every hour at :00 and :30 from 8 a.m. to 6 p.m., about twenty minutes. The usual south exit stop 1 will not be used. Route 2 to the museum: south exit stop 2, departures 9, 10, and 11 a.m., and 1, 2, and 3 p.m., about thirty minutes. The noon service is canceled; other times and the stop are unchanged. Route 3 to the riverside park: north exit stop 4, departures 9:30 and 11:30 a.m., and 1:30 and 3:30 p.m., about fifteen minutes. All services are thirty minutes later than usual. All routes cost 200 yen. Ticket books are sold at the station shop, but cash is also accepted. Keep large luggage out of the aisle. Staff will assist near the stops during works. If the bus company’s telephone is busy, the station information office can also confirm times. Traffic may delay arrivals, so allow extra time.', [
    { prompt: '工事期間中、午前十時に市民病院へ向かうバスに乗りたい人は、どこへ行きますか。', answer: '北口の三番乗り場。', reason: 'The hospital route is temporarily moved to north exit stop 3.', wrong: [['南口の一番乗り場。', 'This is the usual hospital stop, but the notice says it will not be used during works.'], ['南口の二番乗り場。', 'South exit stop 2 is the museum route.'], ['北口の四番乗り場。', 'North exit stop 4 is the riverside park route.']], evidence: '１番　市民病院行き\n乗り場：北口の三番乗り場' },
    { prompt: '工事期間中、正午に中央駅から博物館へ出発するバスはどうなりますか。', answer: '運休する。', reason: 'The museum route explicitly cancels the noon departure.', wrong: [['三十分遅れて出発する。', 'The thirty-minute delay concerns the park route, not the museum’s canceled noon bus.'], ['北口から出発する。', 'The museum stop remains south exit stop 2, and the noon service is canceled.'], ['料金だけが三百円になる。', 'All route fares remain 200 yen.']], evidence: '正午の便は運休します。' },
    { prompt: '時刻を電話で確認したいのに、バス会社につながらない場合、どうできますか。', answer: '駅の案内所でも時刻を確認できる。', reason: 'The notice provides the station information office as an alternative source of timetables.', wrong: [['時刻は駅の売店でしか確認できない。', 'The shop sells ticket books; the named alternative is the information office.'], ['土曜日まで確認できない。', 'Saturday marks restoration of normal operation, not the earliest chance to ask.'], ['帰りのバスの時刻だけを変える。', 'Passengers cannot change service times, and return times are unchanged.']], evidence: '駅の案内所でも時刻を確認できます。' },
  ]);

read('rx-desk', 'Finding the right community desk', 'notice', 'services', 'reading-information',
  'みどり市民センター　生活相談窓口\n暮らしの中で困ったことがある方は、お気軽にご相談ください。相談は無料です。相談する内容によって担当が違います。相談の前に、下の案内を確認してください。どの窓口も、市民センターの二階にあります。\nＡ　住まいの相談\n月曜日・木曜日、午前十時～午後四時。部屋を借りる手続きや、住宅の修理について相談できます。予約が必要です。相談日の二日前までに電話してください。契約書など、内容が分かる物をお持ちください。\nＢ　仕事の相談\n火曜日・金曜日、午前十時～午後五時。仕事の探し方や応募書類の書き方を一緒に考えます。予約は不要です。最後の受付は午後四時半です。書類について相談したい方は、書きかけの物でも持ってきてください。\nＣ　通訳の相談\n水曜日、午後一時～四時。学校や病院などで必要な通訳について、利用できるサービスを案内します。その場で電話を通訳する窓口ではありません。予約は不要です。何のために、いつ通訳が必要か、メモしておくと相談が進みやすくなります。\n相談時間は一人三十分までです。時間内に終わらない場合は、次の相談日を決めます。昼の十二時から一時までは休憩時間です。来られなくなった予約は、前日までに取り消してください。\n足の不自由な方は、建物の東側にあるエレベーターをご利用ください。受付で名前と相談内容を書いてから、担当の窓口へ進んでください。個人の情報は相談のためにだけ使います。',
  'Midori Civic Center: daily-life consultation desks. Consultations are free; staff differ by subject. All desks are on the second floor. A, housing: Mondays and Thursdays, 10 a.m.–4 p.m.; renting procedures and home repairs. Booking required by phone at least two days before the consultation. Bring documents such as a contract that explain the issue. B, employment: Tuesdays and Fridays, 10 a.m.–5 p.m.; help with job searching and application documents. No booking; final reception at 4:30 p.m. Bring documents even if unfinished. C, interpreting: Wednesdays, 1–4 p.m.; information about interpreting services for schools, hospitals, and similar situations. This is not a desk that interprets telephone calls on the spot. No booking. Note what interpreting is for and when it is needed to make the discussion easier. Consultations last up to thirty minutes per person. If that is insufficient, another date will be arranged. Lunch break is noon–1 p.m. Cancel a booked consultation by the previous day if you cannot attend. Visitors with mobility difficulties can use the elevator on the east side. Write your name and topic at reception before going to the appropriate desk. Personal information is used only for the consultation.', [
    { prompt: '仕事の応募書類について、予約なしで相談したい人は、いつ行けばいいですか。', answer: '金曜日の午後二時。', reason: 'Employment consultations are on Tuesday and Friday; two on Friday is within hours and needs no reservation.', wrong: [['月曜日の午前十一時。', 'Monday is a housing-consultation day and requires a reservation.'], ['水曜日の午後二時。', 'Wednesday afternoon is for interpreting-service advice.'], ['金曜日の午後四時四十五分。', 'Employment reception closes at 4:30, so 4:45 is too late for a new consultation.']], evidence: '火曜日・金曜日、午前十時～午後五時。仕事の探し方や応募書類の書き方を一緒に考えます。予約は不要です。最後の受付は午後四時半です。' },
    { prompt: 'Ｃの窓口でできることは何ですか。', answer: '学校などで使える通訳サービスを教えてもらうこと。', reason: 'C introduces available interpreting services and does not itself interpret calls immediately.', wrong: [['その場で病院への電話を必ず通訳してもらうこと。', 'The notice explicitly says C is not an on-the-spot telephone interpreting desk.'], ['住宅の契約書を直してもらうこと。', 'Housing documents belong to A, and rewriting contracts is not promised.'], ['仕事の応募書類を書いてもらうこと。', 'Application-document help belongs to B, not C.']], evidence: '学校や病院などで必要な通訳について、利用できるサービスを案内します。' },
    { prompt: '予約した日に来られなくなった人は、どうすればいいですか。', answer: '前日までに予約を取り消す。', reason: 'The notice requires canceling an unusable reservation by the preceding day.', wrong: [['相談が終わるまで待ってから電話する。', 'Waiting until after the consultation would miss the advance-cancellation deadline.'], ['何も連絡しない。', 'The notice explicitly asks for cancellation.'], ['次の水曜日に、必ず仕事の窓口へ行く。', 'No such replacement is specified, and Wednesday is not an employment-consultation day.']], evidence: '来られなくなった予約は、前日までに取り消してください。' },
  ]);

listen('lx-breakfast', 'Getting ready before leaving', 'daily', 'listening-task',
  '母：健、出かける前に、洗濯機のスイッチを入れてくれる？服はもう入れてあるから。\n健：うん。でも、朝ご飯を先に食べてもいい？\n母：ご飯はまだ温めているところなの。待っている間にお願い。\n健：分かった。洗濯が終わったら、僕が干そうか。\n母：今日は私が家にいるから、干すのは私がやるよ。健は出かけるとき、この封筒をポストに入れてね。\n健：お弁当も持っていくんだよね。\n母：そう。冷蔵庫の上に置いてあるよ。封筒は玄関の棚。\n健：じゃあ、まず洗濯機を動かして、それから朝ご飯にするね。',
  'Mother: Ken, could you switch on the washing machine before going out? The clothes are already inside. Ken: Sure. Can I eat breakfast first? Mother: I am still warming the food, so please do it while you wait. Ken: Understood. Shall I hang the clothes when the wash finishes? Mother: I will be home today, so I will do that. Put this envelope in the mailbox when you leave. Ken: I should take my lunch too, right? Mother: Yes. It is on top of the refrigerator. The envelope is on the entrance shelf. Ken: Then I will start the machine first and have breakfast afterward.', [
    { prompt: '健さんは、まず何をしますか。', answer: '洗濯機のスイッチを入れる。', reason: 'Ken confirms he will start the machine before breakfast.', wrong: [['朝ご飯を食べる。', 'Breakfast is still being heated, and he agrees to start the machine first.'], ['服を外に干す。', 'His mother says she will hang the clothes when washing finishes.'], ['封筒を棚から片付けるだけ。', 'The envelope is to be posted when he goes out; his immediate first task is the machine.']], evidence: 'まず洗濯機を動かして、それから朝ご飯にするね。' },
    { prompt: '洗濯が終わったら、服を干すのは誰ですか。', answer: '健さんのお母さん。', reason: 'The mother explicitly takes responsibility because she will be home.', wrong: [['健さん。', 'Ken offers, but his mother declines and says she will do it.'], ['健さんの友達。', 'No friend is involved in the conversation.'], ['誰も干さない。', 'The mother expressly says she will hang the laundry.']], evidence: '干すのは私がやるよ。' },
    { prompt: '健さんは、出かけるとき、封筒をどうしますか。', answer: 'ポストに入れる。', reason: 'The mother asks Ken to post the envelope when leaving.', wrong: [['冷蔵庫の上に置く。', 'That is the lunch’s location, not the envelope’s destination.'], ['洗濯機に入れる。', 'The washing machine contains clothes; the envelope is to be mailed.'], ['玄関の棚に置いたままにする。', 'The shelf is where the envelope is waiting, but Ken is asked to post it.']], evidence: '出かけるとき、この封筒をポストに入れてね。' },
  ]);

listen('lx-room', 'Arranging a room before visitors arrive', 'home', 'listening-task',
  '彩：午後、友達が来る前に、部屋を少し片付けよう。私は台所を掃除するから、亮はテーブルの上の本を棚に戻してくれる？\n亮：テーブルを窓の近くに動かすんじゃなかった？\n彩：そうだけど、本を置いたままだと重いから、先に本を片付けて。それから二人で動かそう。\n亮：分かった。椅子はどうする？\n彩：四つ必要だよね。ここには三つしかないから、奥の部屋から一つ持ってきて。\n亮：テーブルを動かした後で、椅子を持ってくればいい？\n彩：うん。飲み物は私が用意するから、それで大丈夫。',
  'Aya: Let us tidy a little before our friends come this afternoon. I will clean the kitchen, so could you put the books from the table back on the shelf, Ryo? Ryo: Were we not moving the table near the window? Aya: Yes, but it is heavy with the books on it. Put them away first, then let us move it together. Ryo: Understood. What about chairs? Aya: We need four. There are only three here, so bring one from the back room. Ryo: Should I bring it after moving the table? Aya: Yes. I will prepare drinks, so that is fine.', [
    { prompt: '亮さんは、最初に何をしますか。', answer: 'テーブルの本を棚に戻す。', reason: 'Books must be put away before the heavy table can be moved.', wrong: [['一人でテーブルを動かす。', 'They will move it together after removing the books.'], ['飲み物を用意する。', 'Aya takes responsibility for drinks.'], ['台所を掃除する。', 'Aya, rather than Ryo, will clean the kitchen.']], evidence: '先に本を片付けて。それから二人で動かそう。' },
    { prompt: 'テーブルを動かすのは誰ですか。', answer: '彩さんと亮さんの二人。', reason: 'Aya explicitly says they will move the table together.', wrong: [['亮さんだけ。', 'The agreed plan involves both of them.'], ['来る友達だけ。', 'The preparations occur before the friends arrive.'], ['彩さんだけ。', 'Aya says the two will move it together.']], evidence: 'それから二人で動かそう。' },
    { prompt: 'テーブルを動かした後、亮さんは何をしますか。', answer: '奥の部屋から椅子を一つ持ってくる。', reason: 'Ryo confirms the order and Aya agrees that he should bring the missing chair afterward.', wrong: [['椅子を四つ買いに行く。', 'They already have three and only need one from another room.'], ['友達に飲み物を買ってもらう。', 'Aya will prepare drinks; no such request is made.'], ['本を全部窓の前に積む。', 'The books are to be returned to the shelf before moving the table.']], evidence: 'テーブルを動かした後で、椅子を持ってくればいい？\n彩：うん。' },
  ]);

listen('lx-slides', 'Preparing the presentation materials', 'work', 'listening-task',
  '先輩：明日の説明会の資料、できた？\n後輩：はい。前回の資料を直しました。これから二十部印刷します。\n先輩：ちょっと待って。最後のページの連絡先が変わったんだ。新しい番号をメールで送ったから、先にそこを直して。\n後輩：分かりました。写真も新しくしたほうがいいですか。\n先輩：写真はそのままでいいよ。印刷が終わったら、受付の箱に入れておいて。会場へ運ぶのは私がやるから。\n後輩：メールの番号を確認して、最後のページを直してから印刷します。\n先輩：ありがとう。参加者は十八人だけど、予備に二部あると安心だね。',
  'Senior colleague: Are the materials for tomorrow’s briefing ready? Junior colleague: Yes. I revised the previous version. I am about to print twenty copies. Senior: Wait. The contact information on the last page changed. I emailed the new number, so fix that first. Junior: Understood. Should I replace the photo too? Senior: Leave the photo as it is. Put the printed copies in the box at reception; I will take them to the venue. Junior: I will check the number in the email, correct the last page, and then print. Senior: Thank you. There are eighteen participants, but two spare copies will be reassuring.', [
    { prompt: '後輩は、印刷する前に何をしますか。', answer: 'メールで新しい番号を確認し、最後のページを直す。', reason: 'The last page’s contact number must be corrected using the emailed number before printing.', wrong: [['写真を全部取り替える。', 'The senior says the photo can remain unchanged.'], ['会場へ資料を運ぶ。', 'The senior will transport the documents after printing.'], ['参加者を二十人に増やす。', 'There are eighteen participants; twenty copies includes two spares.']], evidence: 'メールの番号を確認して、最後のページを直してから印刷します。' },
    { prompt: '印刷した資料は、どこに置きますか。', answer: '受付の箱。', reason: 'The senior instructs the junior to put printed copies in the reception box.', wrong: [['会場の窓の前。', 'The junior is not asked to take them directly to the venue.'], ['先輩の家。', 'No home delivery is mentioned.'], ['コピー機の中。', 'Printed documents should be placed in the reception box, not left in the machine.']], evidence: '受付の箱に入れておいて。' },
    { prompt: '二十部印刷する理由は何ですか。', answer: '十八人分と、予備の二部が必要だから。', reason: 'The final line explains eighteen attendee copies plus two spare copies.', wrong: [['参加者が二十人いるから。', 'The stated attendee count is eighteen.'], ['資料のページが二十ページだから。', 'The number of pages is not given and is not the reason for the copy count.'], ['写真を二枚ずつ入れるから。', 'The existing photo remains; photo count does not explain twenty copies.']], evidence: '参加者は十八人だけど、予備に二部あると安心だね。' },
  ]);

listen('lx-parcel', 'Collecting a parcel for someone else', 'services', 'listening-task',
  '客：家族の代わりに、荷物を受け取りに来ました。このお知らせの紙を持ってきたんですが。\n係：ありがとうございます。受け取る方のお名前を確認できる物も必要です。お客様ご自身の物を見せていただけますか。\n客：運転免許証でいいですか。\n係：はい、大丈夫です。では、こちらの用紙に、荷物に書かれているご家族のお名前と、お客様のお名前を書いてください。\n客：住所も書きますか。\n係：住所は、荷物のラベルと確認できたので、書かなくて結構です。お名前を書き終わったら、窓口へお戻りください。荷物をお渡しします。\n客：分かりました。',
  'Customer: I came to collect a parcel for a family member. I brought this notification slip. Clerk: Thank you. We also need something confirming the collector’s name. Could you show your own identification? Customer: Is my driving license acceptable? Clerk: Yes. On this form, write your family member’s name as it appears on the parcel and your own name. Customer: Should I write the address too? Clerk: We have confirmed it against the parcel label, so you need not write it. Return to the counter after filling in the names, and we will hand you the parcel. Customer: Understood.', [
    { prompt: '客は、お知らせの紙のほかに、何を見せますか。', answer: '客自身の運転免許証。', reason: 'The clerk accepts the collector’s own license as identification.', wrong: [['家族の写真だけ。', 'The clerk asks for identification of the person collecting, not merely a family photograph.'], ['店の会員カードだけ。', 'A store card is not mentioned or accepted in the dialogue.'], ['荷物の中身。', 'The parcel has not yet been handed over; its contents are not requested.']], evidence: 'お客様ご自身の物を見せていただけますか。\n客：運転免許証でいいですか。\n係：はい、大丈夫です。' },
    { prompt: '用紙に書く必要があるのは、何ですか。', answer: '家族の名前と、客自身の名前。', reason: 'Both the addressee’s name and the collector’s name are required.', wrong: [['家族の名前と住所だけ。', 'The address need not be written, but the collector’s own name is needed.'], ['客の名前だけ。', 'The form requires both names, not just the collector’s.'], ['荷物の値段と重さ。', 'Neither price nor weight is requested.']], evidence: 'ご家族のお名前と、お客様のお名前を書いてください。' },
    { prompt: '名前を書いた後、客はどうしますか。', answer: '窓口へ戻る。', reason: 'The clerk tells the customer to return to the counter after filling in the names.', wrong: [['そのまま帰る。', 'The customer must return to receive the parcel.'], ['住所を書き直す。', 'The address has already been confirmed and does not need to be written.'], ['荷物を送り直す。', 'This is a collection procedure, not a request to send the parcel again.']], evidence: 'お名前を書き終わったら、窓口へお戻りください。' },
  ]);

listen('lx-gift', 'Choosing a small gift', 'shopping', 'listening-points',
  '店員：何かお探しですか。\n客：友達への小さな贈り物です。千円以内で、旅行に持っていける物がいいんですが。\n店員：こちらの小さいタオルはいかがですか。一枚八百円で、軽いですよ。青と緑があります。赤は売り切れました。\n客：友達は青が好きなので、青を一枚ください。箱に入れてもらえますか。\n店員：箱は二百円ですが、袋なら無料です。\n客：荷物を小さくしたいので、袋でお願いします。\n店員：かしこまりました。贈り物なので、値段の付いた紙は外しておきますね。',
  'Shop assistant: Are you looking for something? Customer: A small gift for a friend. I want something for travel within 1,000 yen. Assistant: How about this small towel? It is light and costs 800 yen. Blue and green are available; red has sold out. Customer: My friend likes blue, so one blue towel, please. Could you put it in a box? Assistant: A box costs 200 yen, but a bag is free. Customer: I want to keep the package small, so a bag, please. Assistant: Certainly. I will remove the price tag since it is a gift.', [
    { prompt: '客は何を買いますか。', answer: '青い小さいタオルを一枚。', reason: 'The customer explicitly orders one blue towel because the friend likes blue.', wrong: [['赤いタオルを二枚。', 'Red towels are sold out, and the customer asks for one blue towel.'], ['緑の大きい箱。', 'Green is an available towel color, not the selected product or a box color.'], ['青い旅行かばん。', 'The desired gift is suitable for travel, but the actual selected product is a towel.']], evidence: '友達は青が好きなので、青を一枚ください。' },
    { prompt: '客が袋を選んだ主な理由は何ですか。', answer: '荷物を小さくしたいから。', reason: 'The customer directly states keeping the package small as the reason.', wrong: [['箱が売り切れたから。', 'Boxes are available for 200 yen.'], ['友達が緑の箱を嫌いだから。', 'No such dislike or green box is mentioned.'], ['タオルを二枚買ったから。', 'Only one towel is ordered.']], evidence: '荷物を小さくしたいので、袋でお願いします。' },
    { prompt: '客はいくら払いますか。', answer: '八百円。', reason: 'One towel is 800 yen and the selected bag is free.', wrong: [['二百円。', 'Two hundred yen is the unused box fee, not the towel price.'], ['千円。', 'This would include the box, but the customer chooses the free bag.'], ['千六百円。', 'That would be two towels; the customer buys only one.']], evidence: '一枚八百円' },
  ]);

listen('lx-hotel', 'Checking luggage and breakfast at a hotel', 'travel', 'listening-points',
  '客：明日、一時ごろ着く予定ですが、部屋に入れますか。\n係：チェックインは午後三時からです。お荷物は午前中からお預かりできます。\n客：では、荷物を置いて、先に町を見て回ります。予約した料金に朝食は付いていますか。\n係：いいえ。朝食は一人千二百円で、前日の夜九時までに受付でお申し込みください。朝は七時から九時までです。\n客：次の日は七時半に出発するので、七時に食べれば間に合いますね。一人分お願いします。\n係：かしこまりました。朝食代も、チェックアウトのときにまとめてお支払いいただけます。',
  'Guest: I expect to arrive around one tomorrow. Can I enter the room? Staff: Check-in starts at 3 p.m. We can keep luggage from the morning. Guest: Then I will leave my luggage and explore town first. Is breakfast included in my booked rate? Staff: No. It costs 1,200 yen per person; apply at reception by 9 p.m. the previous night. Breakfast is from 7 to 9 a.m. Guest: I leave at 7:30 the next day, so I can eat at seven. One breakfast, please. Staff: Certainly. You can pay the breakfast charge together with the rest at checkout.', [
    { prompt: '客は午後一時に着いたら、どうする予定ですか。', answer: '荷物を預けて、町を見て回る。', reason: 'Since the room is unavailable until three, the guest plans to leave luggage and explore.', wrong: [['すぐに部屋に入って寝る。', 'Check-in does not start until 3 p.m.'], ['朝食を食べる。', 'Breakfast is served in the morning from seven to nine.'], ['荷物を持って必ず家に帰る。', 'The hotel can keep the luggage, and the guest plans to explore.']], evidence: '荷物を置いて、先に町を見て回ります。' },
    { prompt: '朝食の申し込みは、いつまでに必要ですか。', answer: '食べる前の日の夜九時まで。', reason: 'The staff gives 9 p.m. on the previous night as the deadline.', wrong: [['食べる日の朝九時まで。', 'Nine in the morning is the end of service, not the booking deadline.'], ['チェックアウトするまで。', 'Checkout is the payment point, not the reservation deadline.'], ['到着日の午後一時より前だけ。', 'The stated deadline is the previous night at nine, not arrival at one.']], evidence: '前日の夜九時までに受付でお申し込みください。' },
    { prompt: '朝食代は、いつ払うことができますか。', answer: 'チェックアウトのとき。', reason: 'The staff permits paying the breakfast charge together at checkout.', wrong: [['朝食を申し込む前だけ。', 'Advance payment before applying is not required.'], ['町を見て回っている途中。', 'Payment is made at hotel checkout, not during sightseeing.'], ['翌週、郵便でだけ。', 'Neither a later postal payment nor such a restriction is described.']], evidence: '朝食代も、チェックアウトのときにまとめてお支払いいただけます。' },
  ]);

listen('lx-buschoice', 'Choosing a bus without transfers', 'transport', 'listening-points',
  '客：明日、九時半までに市民病院へ着きたいんですが、どのバスがいいですか。\n係：八時四十分の直通バスなら、九時二十分に着く予定です。九時のバスに乗って、中央通りで乗り換える方法もありますが、病院に着くのは九時半です。\n客：初めて行くので、乗り換えないほうが安心ですね。八時四十分のにします。\n係：では、南口の一番乗り場からご乗車ください。病院の入口の前が終点です。\n客：切符は先に買いますか。\n係：いいえ、降りるときに二百円を払ってください。お釣りが出ないので、小銭をご用意ください。',
  'Passenger: I want to reach the civic hospital by 9:30 tomorrow. Which bus is best? Staff: The 8:40 direct bus is scheduled to arrive at 9:20. You can also take the nine o’clock bus and transfer at Chuo Street, but that reaches the hospital at 9:30. Passenger: It is my first visit, so no transfer feels more reassuring. I will take the 8:40. Staff: Board at south exit stop 1. The terminus is in front of the hospital entrance. Passenger: Should I buy a ticket first? Staff: No, pay 200 yen when getting off. No change is given, so prepare coins.', [
    { prompt: '客が選んだのは、どのバスですか。', answer: '八時四十分に出る直通バス。', reason: 'The passenger chooses the 8:40 direct service to avoid a transfer.', wrong: [['九時に出る、乗り換えが必要なバス。', 'That is the alternative the passenger decides against.'], ['九時半に駅を出るバス。', 'Nine thirty is an arrival time for the transfer option, not the chosen departure.'], ['中央通りで九時二十分に出るバス。', 'Nine twenty is the direct bus’s arrival time at the hospital.']], evidence: '八時四十分のにします。' },
    { prompt: '客がバスに乗る場所は、どこですか。', answer: '南口の一番乗り場。', reason: 'The staff identifies south exit stop 1 for the chosen direct service.', wrong: [['北口の一番乗り場。', 'The specified exit is south, not north.'], ['中央通りの病院の中。', 'Chuo Street is a transfer point for the other option, not the boarding place for this one.'], ['病院の入口の前。', 'The hospital entrance is the terminus, not the station boarding point.']], evidence: '南口の一番乗り場からご乗車ください。' },
    { prompt: '料金の支払いについて、正しいものはどれですか。', answer: '降りるときに、二百円を小銭で払う。', reason: 'Payment is on alighting and coins are needed because change is not given.', wrong: [['乗る前に必ず切符を買う。', 'The staff says no advance ticket purchase is necessary.'], ['降りた後で、病院の受付に払う。', 'The payment is for the bus and occurs when getting off.'], ['千円札を払えば、必ずお釣りがもらえる。', 'The staff expressly says no change is given.']], evidence: '降りるときに二百円を払ってください。お釣りが出ないので、小銭をご用意ください。' },
  ]);

listen('lx-checkup', 'Changing a health-check appointment', 'health', 'listening-points',
  '受付：健康診断の予約ですね。木曜日の九時半が空いています。\n客：木曜日は仕事があるんです。金曜日はどうですか。\n受付：金曜日なら、午前十時だけ空いています。\n客：では、その時間でお願いします。持っていく物はありますか。\n受付：本人確認ができる物と、予約番号をお持ちください。質問の用紙は、ホームページから印刷して、書いてきていただけます。\n客：家にプリンターがないんですが。\n受付：それなら、こちらで用紙をお渡ししますので、予約の三十分前にお越しください。\n客：分かりました。九時半に行きます。',
  'Receptionist: You are booking a health check, correct? Thursday at 9:30 is available. Customer: I work on Thursday. What about Friday? Receptionist: Only 10 a.m. is available on Friday. Customer: Then that time, please. Should I bring anything? Receptionist: Bring identification and your booking number. You can print the questionnaire from the website and complete it beforehand. Customer: I do not have a printer at home. Receptionist: Then we will give you the form here, so come thirty minutes before your appointment. Customer: Understood. I will come at 9:30.', [
    { prompt: '予約した健康診断は、いつ始まりますか。', answer: '金曜日の午前十時。', reason: 'The customer accepts the only Friday appointment, at ten.', wrong: [['木曜日の午前九時半。', 'The customer cannot attend Thursday because of work.'], ['金曜日の午前九時半。', 'Nine thirty is the arrival time for filling in the form, not the appointment start.'], ['木曜日の午後十時。', 'No evening appointment is offered, and Thursday is unsuitable.']], evidence: '金曜日なら、午前十時だけ空いています。\n客：では、その時間でお願いします。' },
    { prompt: '客は、なぜ予約の三十分前に行きますか。', answer: '受付でもらう質問の用紙を書くため。', reason: 'Without a home printer, the customer will receive the form there and arrive early to complete it.', wrong: [['健康診断の予約が九時半に変わったから。', 'The appointment remains at ten; only arrival is earlier.'], ['木曜日の仕事を休むため。', 'The booked day is Friday, and early arrival does not concern Thursday’s job.'], ['ホームページを作るため。', 'The customer is using a questionnaire, not creating a website.']], evidence: 'こちらで用紙をお渡ししますので、予約の三十分前にお越しください。' },
    { prompt: '客が持っていく必要がある物は、どれですか。', answer: '本人確認ができる物と予約番号。', reason: 'The receptionist directly lists identification and the booking number.', wrong: [['プリンターとパソコン。', 'The customer does not need to bring a printer; the form will be provided.'], ['仕事の予定表だけ。', 'A work schedule is not one of the requested items.'], ['書いた質問の用紙だけで、本人確認の物は不要。', 'Identification is explicitly required, and the customer will receive the form on arrival.']], evidence: '本人確認ができる物と、予約番号をお持ちください。' },
  ]);

listen('lx-talk', 'A small conversation at the bus stop', 'people', 'listening-outline',
  '私は以前、近所の人に会っても、あいさつをしてすぐに別れていました。何を話せばいいか分からなかったからです。ある朝、バスを待っているとき、隣にいた人が「今日は寒いですね」と言いました。短い返事をすると、その人は近くの店の話をしてくれました。長い話をしなくても、お互いに少し笑って、一日を気持ちよく始められました。それからは、私も天気や花の話をしてみるようになりました。相手が急いでいるときは、あいさつだけで終わります。大事なのは、たくさん話すことより、相手の様子を見ながら、短い会話を少しずつ重ねることだと思います。',
  'I used to greet neighbors and immediately leave because I did not know what to discuss. One morning while waiting for a bus, the person beside me remarked on the cold weather. After my brief reply, they told me about a nearby shop. Even without a long conversation, we shared a little smile and began the day pleasantly. Since then, I have tried talking about the weather and flowers. If someone is in a hurry, I stop after greeting them. I think what matters is not speaking a lot but noticing the other person’s situation and gradually sharing brief conversations.', [
    { prompt: 'この話の主な内容は何ですか。', answer: '近所の人との短い会話を、少しずつ続けること。', reason: 'The account moves from avoiding conversation to valuing gradual brief exchanges with neighbors.', wrong: [['バスの本数を増やすこと。', 'The bus stop is the setting of an encounter, not a transport-policy topic.'], ['店を開くための準備。', 'A shop is mentioned as a conversational topic, not a business project.'], ['寒い日に外へ出ない方法。', 'Cold weather starts the conversation, but avoiding the outdoors is not the point.']], evidence: '短い会話を少しずつ重ねることだと思います。' },
    { prompt: 'この人の考えは、経験の後、どのように変わりましたか。', answer: '長く話さなくても、気持ちのよい交流ができると思うようになった。', reason: 'The brief bus-stop conversation shows that a long talk is unnecessary for a pleasant exchange.', wrong: [['あいさつは全く必要ないと思うようになった。', 'The speaker still greets people, including when they are in a hurry.'], ['会話はいつも一時間以上必要だと思うようになった。', 'The account emphasizes short exchanges, not lengthy ones.'], ['知らない店の話は全部避けたいと思うようになった。', 'The shop conversation was a positive part of the encounter.']], evidence: '長い話をしなくても、お互いに少し笑って、一日を気持ちよく始められました。' },
    { prompt: '話している人は、会話をするとき、何を大切にしていますか。', answer: '相手の様子に合わせて、話す量を考えること。', reason: 'The speaker watches the other person’s situation and limits conversation to greetings when they are rushed.', wrong: [['急いでいる人にも、必ず長く話すこと。', 'The speaker does the opposite, ending after a greeting when the other person is rushed.'], ['自分の話だけを続けること。', 'The closing point is sensitivity to the other person, not one-sided speech.'], ['同じ店の話しかしてはいけないこと。', 'Weather and flowers are also mentioned as possible topics.']], evidence: '相手の様子を見ながら' },
  ]);

listen('lx-explain', 'Checking learning by explaining it', 'education', 'listening-outline',
  '試験の勉強をするとき、私は大切なところに線を引くだけで、覚えたつもりになっていました。ところが、友達に説明してみると、言葉は覚えていても、意味がよく分かっていないことに気づきました。そこで、今は本を閉じて、今日勉強したことを短い言葉で説明する練習をしています。うまく説明できないところだけ、もう一度本を読みます。全部を何度も読むより、自分が分からないところがはっきりするので、勉強の時間を使いやすくなりました。線を引くのをやめたわけではありません。線を引いた後で、本当に説明できるか確かめることが大切だと感じています。',
  'When studying for tests, I used to think I had learned material simply by underlining the important parts. But when I tried explaining it to a friend, I realized that even when I remembered the words I did not fully understand their meaning. Now I close the book and practice briefly explaining what I studied that day. I reread only the parts I cannot explain well. This makes my gaps clearer than repeatedly rereading everything and helps me use study time effectively. I have not stopped underlining; I feel it matters to check afterward whether I can actually explain what I marked.', [
    { prompt: 'この人は、主にどんな勉強方法について話していますか。', answer: '本を閉じて説明し、理解できているか確かめる方法。', reason: 'The whole account concerns testing understanding through explanation without looking at the book.', wrong: [['大切なところを見ずに全部消す方法。', 'The speaker still marks important passages; deleting them is not described.'], ['友達の代わりに試験を受ける方法。', 'The friend helps reveal a comprehension gap; taking a test for them is not discussed.'], ['本を買わずに表紙だけ覚える方法。', 'The method works with studied content, not book covers.']], evidence: '本を閉じて、今日勉強したことを短い言葉で説明する練習' },
    { prompt: 'この人が新しい方法を始めた理由は何ですか。', answer: '言葉を覚えていても、意味を理解していないことに気づいたから。', reason: 'Trying to explain to a friend exposed the difference between remembering wording and understanding.', wrong: [['線を引く道具がなくなったから。', 'No shortage of tools is mentioned, and underlining continues.'], ['友達に本を全部捨てられたから。', 'The friend listens to an explanation; no books are discarded.'], ['試験では説明が絶対に禁止されているから。', 'No exam prohibition is discussed; the method is for studying.']], evidence: '言葉は覚えていても、意味がよく分かっていないことに気づきました。' },
    { prompt: 'この人が、最後に大切だと言っているのは何ですか。', answer: '線を引くだけで終わらず、説明できるか確かめること。', reason: 'The conclusion explicitly adds a check of understanding after underlining.', wrong: [['線を引くことは必ずやめること。', 'The speaker says they have not stopped underlining.'], ['分かっているところも全部同じ回数読むこと。', 'Only difficult-to-explain parts are reread.'], ['覚えた言葉の数だけで理解を判断すること。', 'The story shows that remembering words alone does not prove understanding.']], evidence: '線を引いた後で、本当に説明できるか確かめることが大切' },
  ]);

listen('lx-leaves', 'Noticing the seasons in one tree', 'nature', 'listening-outline',
  '散歩をするとき、以前の私は、いつも同じ公園ではつまらないと思って、毎回違う道を選んでいました。でも、足を痛めて遠くまで歩けなかった時期に、家の前の木を毎日見るようになりました。初めは変化がないように見えましたが、一週間たつと、小さな葉が増えていることに気づきました。雨の翌日は色が明るく見え、風の日は葉の音がよく聞こえました。近い場所でも、同じ物を続けて見れば、いろいろな発見があるのですね。今は遠くへ行ける日もありますが、ときどきその木を見に戻ります。新しい場所を探すだけでなく、知っている場所の変化にも気づいていたいと思います。',
  'On walks, I used to choose a different road every time because I thought the same park was boring. But during a period when a sore foot prevented long walks, I began looking at the tree in front of my home every day. At first it seemed unchanged, but after a week I noticed more small leaves. The day after rain, the colors looked brighter, and on windy days the sound of the leaves was clear. Even somewhere nearby, repeatedly observing the same thing brings discoveries. I can go farther on some days now, but occasionally return to that tree. I want to notice changes in familiar places, not just search for new ones.', [
    { prompt: 'この話で、中心になっている考えは何ですか。', answer: 'よく知っている場所にも、観察を続ければ発見がある。', reason: 'The repeated observations of the nearby tree illustrate discoveries in a familiar place.', wrong: [['毎日違う公園に行かなければならない。', 'The speaker’s old preference changes toward observing a familiar tree.'], ['雨の日は木の変化が全く分からない。', 'After rain, the tree’s colors looked brighter.'], ['遠くへ歩くことだけが散歩の目的だ。', 'The conclusion values discoveries nearby, not only distance.']], evidence: '近い場所でも、同じ物を続けて見れば、いろいろな発見がある' },
    { prompt: '話している人の見方は、どのように変わりましたか。', answer: '同じ場所はつまらないと思っていたが、変化に気づく面白さを知った。', reason: 'The opening boredom contrasts with the later enjoyment of leaves, color, and sound changing.', wrong: [['近い場所には何もないと、さらに強く思うようになった。', 'The observations lead to the opposite realization.'], ['木を見るのを完全にやめるようになった。', 'The speaker still returns to the tree.'], ['葉の色はいつも同じだと決めるようになった。', 'The speaker notices color differences after rain.']], evidence: '以前の私は、いつも同じ公園ではつまらないと思って' },
    { prompt: '話している人は、これからも何を意識したいと思っていますか。', answer: '新しい場所だけでなく、身近な場所の変化も見ること。', reason: 'The final sentence explicitly values familiar places’ changes alongside new destinations.', wrong: [['知っている場所には二度と戻らないこと。', 'The speaker deliberately returns to the tree.'], ['木の音を聞かず、写真だけを見ること。', 'Leaf sounds are part of the discoveries; photos are not the focus.'], ['散歩中は何も見ないこと。', 'The whole account encourages noticing surroundings.']], evidence: '知っている場所の変化にも気づいていたい' },
  ]);

listen('lx-calendar', 'Sharing a calendar without sharing everything', 'technology', 'listening-outline',
  '家族で予定を合わせるために、スマートフォンの同じカレンダーを使い始めました。最初は、すべての予定を書けば便利だと思いました。でも、小さな用事まで全部入れると、画面がいっぱいになって、家族で確認したい大事な予定が見つけにくくなりました。話し合って、全員に関係する予定だけを共有することにしました。例えば、夕食が要らない日や、家の修理がある日です。自分だけの用事は、それぞれのカレンダーに書きます。今は、必要な情報がすぐ見つかり、確認の連絡も減りました。便利な道具でも、何を共有するか決めてから使うと、もっと役に立つと思います。',
  'My family began using the same smartphone calendar to coordinate plans. At first, I thought putting every plan in it would be convenient. But filling it with minor errands crowded the screen and made important family information hard to find. After discussing it, we decided to share only plans relevant to everyone, such as days when someone does not need dinner or when repairs will happen at home. Personal errands go in individual calendars. Now we can quickly find necessary information and need fewer confirmation messages. I think even a convenient tool becomes more useful when we decide what to share before using it.', [
    { prompt: 'この人は、主に何について話していますか。', answer: '共有する予定を選んで、家族のカレンダーを使いやすくしたこと。', reason: 'The story explains how reducing shared information made the family calendar more useful.', wrong: [['スマートフォンを家族全員が捨てたこと。', 'The family continues using calendars on smartphones.'], ['修理の予定を家族に知らせないこと。', 'Household repairs are explicitly an example of information to share.'], ['全員の小さな用事をもっと細かく書くこと。', 'Overloading the calendar with minor errands was the problem, not the solution.']], evidence: '全員に関係する予定だけを共有することにしました。' },
    { prompt: '初めの使い方には、どんな問題がありましたか。', answer: '予定が多すぎて、大事な情報が見つけにくかった。', reason: 'Too many minor plans filled the screen and obscured important shared dates.', wrong: [['家族で相談する予定が一つもなかった。', 'The problem is excessive entries, not an absence of plans.'], ['自分だけのカレンダーが使えなかった。', 'Individual calendars are used successfully after the change.'], ['夕食の予定だけが自動で消えた。', 'No automatic deletion is mentioned.']], evidence: '大事な予定が見つけにくくなりました。' },
    { prompt: '最後に、この人が伝えたいことは何ですか。', answer: '道具を使う前に、共有する情報を考えるとよい。', reason: 'The conclusion identifies deciding what to share as the reason the tool becomes more helpful.', wrong: [['情報は多いほど必ず便利になる。', 'The example shows excessive information making the calendar less useful.'], ['家族に関係する予定も自分だけで管理するべきだ。', 'The family intentionally shares plans relevant to everyone.'], ['カレンダーでは予定を確認できない。', 'The revised calendar makes confirmation easier.']], evidence: '何を共有するか決めてから使うと、もっと役に立つ' },
  ]);

// Expression items replace picture cues with explicit spoken descriptions of situations.
listen('lx-volunteer', 'What to say while helping at a local event', 'community', 'listening-expression',
  'これは、場面を言葉で説明する表現の練習です。\n場面一。あなたは町のお祭りの準備をしています。重い箱を一人では運べないので、隣にいる人に手伝ってほしいと思っています。\n場面二。準備が終わり、担当の人があなたに次の日も来られるか聞きました。しかし、次の日は仕事があるため、来られません。理由を伝えて、丁寧に断りたいと思っています。\n場面三。初めて来た人が、受付の場所が分からず困っています。あなたは受付が入口の右側にあると知っているので、その場所を教えようとしています。',
  'This is expression practice with situations described in words. Situation 1: you are preparing a town festival. You cannot carry a heavy box alone and want the person next to you to help. Situation 2: after preparations, the person in charge asks whether you can come the following day too. You cannot because you have work, and want to explain and politely decline. Situation 3: a first-time visitor cannot find reception. You know it is to the right of the entrance and want to explain its location.', [
    { prompt: '場面一で、手伝いを頼むとき、何と言いますか。', answer: 'すみません、この箱を一緒に運んでいただけませんか。', reason: 'This politely requests help carrying the heavy box together.', wrong: [['この箱は、もう運び終わりました。', 'That reports completion instead of asking for the needed help.'], ['ここで箱を売ってもいいですか。', 'The situation is about carrying a box, not requesting permission to sell it.'], ['一人で運べるので、手伝わないでください。', 'This refuses help and contradicts the stated inability to carry it alone.']], evidence: '重い箱を一人では運べないので、隣にいる人に手伝ってほしい' },
    { prompt: '場面二で、丁寧に断るとき、何と言いますか。', answer: '申し訳ありません。明日は仕事があって、来られません。', reason: 'This politely declines and gives the stated work-related reason.', wrong: [['明日も、何時でも大丈夫です。', 'This accepts unrestricted attendance, contradicting the work commitment.'], ['今日の仕事はもう終わりました。', 'That says today’s work has ended and does not decline tomorrow’s invitation.'], ['明日は来ていただけませんか。', 'This asks the other person to come, instead of explaining that the speaker cannot attend.']], evidence: '次の日は仕事があるため、来られません。' },
    { prompt: '場面三で、受付の場所を教えるとき、何と言いますか。', answer: '受付は、入口を入って右側にあります。', reason: 'This gives the known reception location to the right of the entrance.', wrong: [['受付がどこか、私にも分かりません。', 'The speaker knows the location and is trying to explain it.'], ['入口の左側でお待ちください。', 'The stated reception location is on the right, not the left.'], ['受付には行かないでください。', 'The visitor needs directions to reception, not a prohibition on going there.']], evidence: '受付が入口の右側にある' },
  ]);

listen('lx-gallery', 'What to say at a small exhibition', 'culture', 'listening-expression',
  'これは、写真を使わず、場面を言葉で示す表現の練習です。\n場面一。あなたは作品の展示を見に来ました。係の人に、作品の写真を撮ってもよいか確かめたいと思っています。\n場面二。友達が作った作品を見て、色の組み合わせが美しいと思いました。その気持ちを友達に伝えたいと思っています。\n場面三。帰る時間になりました。案内してくれた人にお礼を言ってから、会場を出たいと思っています。案内してもらったおかげで、作品が前よりよく分かりました。',
  'This is expression practice using verbal situations instead of pictures. Situation 1: you are visiting an exhibition and want to ask a staff member whether photographing the works is allowed. Situation 2: you see a friend’s work and find its color combination beautiful; you want to tell the friend. Situation 3: it is time to leave. Before leaving the venue, you want to thank the person who guided you, because their guidance helped you understand the works better.', [
    { prompt: '場面一で、写真を撮る前に、何と言いますか。', answer: 'この作品の写真を撮ってもよろしいですか。', reason: 'This politely asks permission before photographing the work.', wrong: [['この写真を撮ってくださって、ありがとうございました。', 'This thanks someone for a photograph already taken instead of requesting permission.'], ['この作品を必ず買ってください。', 'This asks someone to buy the work and does not check photography rules.'], ['この会場には写真がありません。', 'This statement does not ask whether taking a photograph is allowed.']], evidence: '作品の写真を撮ってもよいか確かめたい' },
    { prompt: '場面二で、友達に気持ちを伝えるなら、何と言いますか。', answer: 'この色の組み合わせ、すてきですね。', reason: 'This directly expresses appreciation for the color combination.', wrong: [['作品を見てはいけません。', 'The speaker wants to compliment the work, not prohibit viewing it.'], ['色の名前を全部忘れてください。', 'Asking the friend to forget color names does not express admiration.'], ['この作品は、まだ見ていません。', 'The speaker has already seen it and liked the colors.']], evidence: '色の組み合わせが美しいと思いました。' },
    { prompt: '場面三で、帰る前に、何と言いますか。', answer: 'ご案内ありがとうございました。おかげでよく分かりました。', reason: 'This thanks the guide and explains the stated benefit of the guidance.', wrong: [['案内してください。まだ何も見ていません。', 'The visit and guidance have already happened.'], ['これから作品を作り始めます。', 'The speaker is leaving after viewing, not beginning to create a work.'], ['会場には来られませんでした。', 'The speaker is currently at the venue and about to leave.']], evidence: '案内してもらったおかげで、作品が前よりよく分かりました。' },
  ]);

listen('lx-reassure', 'Responding to thanks and feelings', 'feelings', 'listening-response',
  '三つの短い発言を聞いて、それぞれに合う返事を選んでください。\n発言一。「この前、引っ越しを手伝ってくれて、ありがとう。本当に助かったよ。」\n発言二。「面接が明日なので、少し不安なんです。準備はしたんですが、うまく話せるか心配で。」\n発言三。「なくした財布が見つかって、本当に安心しました。駅の人が保管してくれていたんです。」',
  'Listen to three short utterances and choose an appropriate reply to each. Utterance 1: “Thank you for helping me move the other day. It really helped.” Utterance 2: “My interview is tomorrow, so I am a little anxious. I prepared, but I am worried whether I can speak well.” Utterance 3: “I was really relieved that my lost wallet was found. The station staff had kept it for me.”', [
    { prompt: '発言一への返事として、最も適切なものはどれですか。', answer: 'どういたしまして。役に立ててよかったよ。', reason: 'This acknowledges thanks and says the speaker is pleased to have helped.', wrong: [['お大事に。早く元気になってね。', 'This wishes recovery from illness, which is not the situation described.'], ['いただきます。とてもおいしそうです。', 'This is a meal-opening response, not an answer to thanks for moving help.'], ['お邪魔します。ここで靴を脱ぎますね。', 'This announces entering someone’s home, not acknowledging the thanks.']], evidence: '引っ越しを手伝ってくれて、ありがとう。' },
    { prompt: '発言二への返事として、最も適切なものはどれですか。', answer: '準備してきたんですから、落ち着いて話せるといいですね。応援しています。', reason: 'This responds supportively to anxiety about tomorrow’s interview without assuming an outcome.', wrong: [['合格したんですね。おめでとうございます。', 'The interview has not happened yet, so success has not been announced.'], ['ご飯は何杯にしますか。', 'A question about rice portions does not address the interview anxiety.'], ['この荷物は明日までに届きます。', 'A parcel-delivery statement does not respond to the expressed worry.']], evidence: '面接が明日なので、少し不安なんです。' },
    { prompt: '発言三への返事として、最も適切なものはどれですか。', answer: 'それはよかったですね。見つかって安心しましたね。', reason: 'This shares the relief that the wallet has been found.', wrong: [['窓を閉めてもよろしいですか。', 'Asking about a window does not respond to the recovered-wallet news.'], ['この店は水曜日だけ安いです。', 'A shop-discount statement is unrelated to the relief described.'], ['駅までの切符を二枚ください。', 'Buying tickets does not acknowledge the found wallet.']], evidence: 'なくした財布が見つかって、本当に安心しました。' },
  ]);

listen('lx-requests', 'Responding to small requests', 'communication', 'listening-response',
  '三つの発言を聞いて、相手への返事を選んでください。\n発言一。「この席、空いていますか。隣に座ってもいいですか。」\n発言二。「会議の時間が変わったこと、田中さんにも伝えておいてもらえますか。」\n発言三。「すみません、最後の部分が聞き取れませんでした。もう一度、ゆっくり言っていただけますか。」',
  'Listen to three utterances and choose a reply to the speaker. Utterance 1: “Is this seat free? May I sit beside you?” Utterance 2: “Could you also tell Tanaka that the meeting time has changed?” Utterance 3: “Sorry, I could not catch the last part. Could you say it again slowly?”', [
    { prompt: '発言一への返事として、座ってよいことを伝えるなら、どれですか。', answer: 'ええ、空いています。どうぞ。', reason: 'This confirms the seat is free and grants permission to sit.', wrong: [['会議は三時に変更になりました。', 'This gives meeting information, not permission to use the seat.'], ['席の番号をもう一度書いてください。', 'This asks for a number and does not tell the person they may sit.'], ['今から引っ越しを手伝います。', 'Moving assistance does not answer the seating request.']], evidence: '隣に座ってもいいですか。' },
    { prompt: '発言二への返事として、依頼を引き受けるなら、どれですか。', answer: '分かりました。田中さんに連絡しておきます。', reason: 'This accepts the request and promises to pass the information to Tanaka.', wrong: [['田中さんは、ここに座ってもいいです。', 'Seating permission does not convey the changed meeting time.'], ['時間は聞き取れたので、もう言わないでください。', 'This does not agree to relay the information to Tanaka.'], ['この写真を撮ってもよろしいですか。', 'Photography permission is unrelated to the requested contact.']], evidence: '田中さんにも伝えておいてもらえますか。' },
    { prompt: '発言三への返事として、最も適切なものはどれですか。', answer: 'はい。では、最後の部分をゆっくり言いますね。', reason: 'This agrees to repeat the specific portion slowly, as requested.', wrong: [['では、もっと速く言います。', 'The request is for slower speech, not faster.'], ['その荷物は、もう送りました。', 'Parcel information does not address the request to repeat speech.'], ['最後まで聞けたんですね。よかったです。', 'The speaker explicitly says they could not catch the last part.']], evidence: 'もう一度、ゆっくり言っていただけますか。' },
  ]);

// Extra brochure notes keep information-retrieval texts near the N3 practice length (~600 Japanese characters).
const brochureNotes = [
  { id: 'rx-bag', ja: 'お手入れで落ちない汚れもあります。作業前に残る可能性がある部分を説明しますので、不安な点はご質問ください。', en: 'Some stains cannot be removed by cleaning. We will explain any areas that may remain before starting, so please ask about concerns.' },
  { id: 'rx-trips', ja: '参加する方は、出発の十分前までにお集まりください。集合後に、係が名前を確認してからバスへご案内します。', en: 'Please gather at least ten minutes before departure. After checking participants’ names, staff will guide you to the bus.' },
  { id: 'rx-buses', ja: '車内では次の停留所を放送します。降りる停留所が分からない場合は、乗るときに運転手にお伝えください。忘れ物の問い合わせは、バス会社へお願いします。', en: 'The next stop is announced on the bus. If you do not know which stop to use, tell the driver when boarding. Contact the bus company about lost property.' },
];
for (const note of brochureNotes) {
  const passage = expandedReadings.find(item => item.id === note.id)!;
  passage.body += `\n${note.ja}`;
  passage.translation += ` ${note.en}`;
}

// Additional original listening practice. Append-only to preserve earlier passage/question identities.
listen('lx-more-dinner', 'Preparing dinner in the right order', 'food', 'listening-task',
  '父：夕飯の準備を少し手伝ってくれる？野菜は洗ってあるから、冷蔵庫の魚を三人分に切っておいて。\n娘：分かった。先にご飯を炊いたほうがいい？\n父：ご飯はもう炊いたよ。まず魚をお願い。焼くのは、僕が帰ってからやるから。\n娘：魚を切った後は、何をすればいい？\n父：洗ってある野菜でサラダを作って。ドレッシングは、食べる直前にかけよう。\n娘：じゃあ、魚を切って、サラダを作っておくね。買い物は必要？\n父：今日は何も買わなくて大丈夫。四十分ぐらいで帰るよ。',
  'Father: Could you help prepare dinner? The vegetables are washed, so please cut the fish in the refrigerator into three portions. Daughter: Understood. Should I cook rice first? Father: I have already cooked it. Start with the fish. I will cook the fish when I get home. Daughter: What should I do after cutting it? Father: Make a salad with the washed vegetables. We will add the dressing just before eating. Daughter: Then I will cut the fish and prepare the salad. Do we need any shopping? Father: No, we do not need to buy anything today. I will be back in about forty minutes.', [
    { prompt: '娘は、まず何をしますか。', answer: '冷蔵庫の魚を三人分に切る。', reason: 'The father has already cooked the rice and explicitly asks her to start by cutting the fish.', wrong: [['ご飯を炊く。', 'Rice was already cooked by the father, so this is not her first task.'], ['サラダにドレッシングをかける。', 'The salad comes after cutting the fish, and dressing is added only just before eating.'], ['買い物に出かける。', 'The father says no shopping is needed today.']], evidence: 'まず魚をお願い。' },
    { prompt: '魚を切った後、娘は何をしますか。', answer: '洗ってある野菜でサラダを作る。', reason: 'In answer to the daughter’s question about the next task, the father tells her to make the salad.', wrong: [['魚を焼く。', 'The father will cook the fish after he returns.'], ['野菜を買ってくる。', 'The vegetables are already washed and ready, and no shopping is needed.'], ['ご飯を炊き直す。', 'The rice is ready; no one requests cooking it again.']], evidence: '洗ってある野菜でサラダを作って。' },
    { prompt: '魚を焼くのは、誰が、いつしますか。', answer: '父が、帰ってからする。', reason: 'The father reserves the cooking step for himself after he gets home.', wrong: [['娘が、サラダを作る前にする。', 'The daughter prepares the fish and salad; the father will cook the fish later.'], ['父が、買い物に行く前にする。', 'He says he will do it after returning, and does not mention a shopping trip.'], ['娘が、父が帰る前にする。', 'The father specifically says he will cook the fish after he returns.']], evidence: '焼くのは、僕が帰ってからやるから。' },
  ]);
listen('lx-more-library-help', 'Sorting books for a reading event', 'education', 'listening-task',
  '先生：茜さん、読書会で使う本を机に並べるのを手伝ってもらえる？\n茜：はい。本の名前の順に並べますか。\n先生：今回は、大きさの順にして。大きい本を右、小さい本を左に置くと、手に取りやすいから。\n茜：分かりました。全部並べればいいですか。\n先生：その前に、表紙が破れている本が三冊あるので、まずその三冊だけ、奥の棚に置いて。修理してから使う予定なの。\n茜：残りの本を、大きさの順に並べるんですね。案内の紙も印刷しましょうか。\n先生：それは司書さんが用意してくれるから、大丈夫。\n茜：では、先に破れている本を分けます。',
  'Teacher: Akane, could you help arrange the books for the reading event on the table? Akane: Yes. Should I arrange them by title? Teacher: This time, by size. Put larger books on the right and smaller ones on the left so they are easy to pick up. Akane: Understood. Should I arrange all of them? Teacher: Before that, three books have torn covers. First put just those three on the shelf at the back. We plan to use them after repairing them. Akane: Then I arrange the remaining books by size. Shall I print the information sheets too? Teacher: The librarian will prepare those, so that is fine. Akane: Then I will separate the damaged books first.', [
    { prompt: '茜さんは、最初に何をしますか。', answer: '表紙が破れている三冊を、奥の棚に置く。', reason: 'The teacher adds a step before arranging the books: separate the three with torn covers.', wrong: [['案内の紙を印刷する。', 'The librarian will prepare the information sheets; Akane does not need to print them.'], ['全部の本を名前の順に並べる。', 'The teacher rejects title order and asks her to separate damaged books before arranging the rest.'], ['小さい本を全部、修理する。', 'Only the three books with torn covers need repair; their size is not given.']], evidence: 'まずその三冊だけ、奥の棚に置いて。' },
    { prompt: '残りの本は、どのように並べますか。', answer: '大きさの順に、大きい本を右に並べる。', reason: 'The teacher specifies size order, with large books on the right and small books on the left.', wrong: [['本の名前の順に並べる。', 'Title order is Akane’s initial suggestion, but the teacher asks for size order.'], ['小さい本を右、大きい本を左に並べる。', 'This reverses the positions stated by the teacher.'], ['表紙の色ごとに並べる。', 'The instruction uses size, not cover color.']], evidence: '大きい本を右、小さい本を左に置く' },
    { prompt: '案内の紙を用意するのは、誰ですか。', answer: '司書さん。', reason: 'The teacher explains that the librarian will prepare the information sheets.', wrong: [['茜さん。', 'Akane offers to print the sheets, but the teacher says the librarian will do it.'], ['読書会に来る人。', 'Participants are not assigned the preparation of information sheets.'], ['本を修理する人と、必ず同じ人。', 'The speaker does not identify the repairer; only the librarian’s responsibility for the sheets is stated.']], evidence: 'それは司書さんが用意してくれるから' },
  ]);
listen('lx-more-cleanup-message', 'A recorded message about tomorrow’s cleanup', 'community', 'listening-task',
  '地域の清掃活動に申し込んだ皆さんへの連絡です。明日は気温が高くなる予報なので、開始を午前九時から八時半に変更します。場所は変わらず、公園の西の入口です。いつもの北の入口ではありませんので、ご注意ください。時間が変わりましたので、このメッセージを聞いた方は、参加できるかどうか、今日の午後六時までにメールでお返事ください。来られない方も、必ずお願いします。ごみ袋はこちらで用意します。皆さんは、軍手と飲み物を持ってきてください。活動は一時間ほどで終わる予定です。',
  'This message is for everyone who signed up for the local cleanup. Since high temperatures are forecast tomorrow, the start time has changed from 9 a.m. to 8:30 a.m. The location is unchanged: the park’s west entrance. Please note that it is not the usual north entrance. Because the time has changed, everyone who hears this message should reply by email by 6 p.m. today to say whether they can attend. Those unable to come should also reply. We will provide rubbish bags. Please bring work gloves and a drink. The activity is expected to finish in about an hour.', [
    { prompt: 'このメッセージを聞いた人は、今日、何をしなければなりませんか。', answer: '午後六時までに、参加できるかメールで返事をする。', reason: 'All recipients, including those unable to attend, must confirm availability by email today.', wrong: [['来られない場合だけ、明日の朝に電話する。', 'Both attendees and non-attendees must reply today by email, not tomorrow by phone.'], ['公園へ行って、ごみ袋を受け取る。', 'Rubbish bags will be provided for the activity; no advance collection visit is requested.'], ['北の入口に九時に集まる。', 'That describes neither today’s required reply nor tomorrow’s updated meeting arrangements.']], evidence: '参加できるかどうか、今日の午後六時までにメールでお返事ください。' },
    { prompt: '明日の集合について、正しいものはどれですか。', answer: '午前八時半に、公園の西の入口へ行く。', reason: 'The start is now 8:30, and the designated entrance is the west entrance.', wrong: [['午前九時に、公園の北の入口へ行く。', 'Nine o’clock is the old time, and the north entrance is explicitly excluded.'], ['午前八時半に、公園の北の入口へ行く。', 'The new time is correct, but the entrance should be west, not north.'], ['午後六時に、公園の西の入口へ行く。', 'Six p.m. is today’s email deadline, not tomorrow’s meeting time.']], evidence: '開始を午前九時から八時半に変更します。場所は変わらず、公園の西の入口です。' },
    { prompt: '参加者が自分で持っていく物は、どれですか。', answer: '軍手と飲み物。', reason: 'Participants are specifically asked to bring gloves and a drink; the organizers supply bags.', wrong: [['ごみ袋だけ。', 'Rubbish bags are supplied by the organizers.'], ['軍手と、必ず一時間分の時計。', 'Gloves are required, but no clock is requested; one hour describes the activity’s duration.'], ['飲み物と、北の入口の地図だけ。', 'Participants also need gloves, and the meeting point is the west entrance.']], evidence: '皆さんは、軍手と飲み物を持ってきてください。' },
  ]);
listen('lx-more-inspection', 'Information about an apartment inspection', 'home', 'listening-points',
  '管理会社からのお知らせです。来週の火曜日、各部屋の水道を点検します。午前は一階と二階、午後は三階と四階を回ります。三階の方は、午後一時から三時までの間、ご在宅ください。点検は一部屋十五分ほどです。その時間に家にいられない場合は、今週の金曜日までに管理会社へ電話してください。別の日をご相談します。作業員は、会社名の入った名札を付けています。点検のためにその場で料金をお支払いいただくことはありません。',
  'This is a notice from the property management company. Next Tuesday we will inspect the water supply in each apartment. We will visit the first and second floors in the morning, and the third and fourth floors in the afternoon. Residents of the third floor should be home between 1 and 3 p.m. Each apartment’s inspection takes about fifteen minutes. If you cannot be home during that time, call the management company by this Friday to discuss another day. Workers will wear name badges showing the company name. You will not be asked to pay an inspection fee on the spot.', [
    { prompt: '三階に住んでいる人は、いつ家にいる必要がありますか。', answer: '来週の火曜日、午後一時から三時まで。', reason: 'The notice specifically gives the third-floor home-availability window as Tuesday afternoon, one to three.', wrong: [['今週の金曜日、午前一時から三時まで。', 'Friday is the contact deadline; the inspection is next Tuesday afternoon.'], ['来週の火曜日、午前中だけ。', 'Morning visits are for floors one and two, not the third floor.'], ['来週の火曜日、午後三時から五時まで。', 'The stated window is one to three, not three to five.']], evidence: '三階の方は、午後一時から三時までの間、ご在宅ください。' },
    { prompt: 'その時間に家にいられない人は、どうしますか。', answer: '今週の金曜日までに、管理会社に電話する。', reason: 'Unavailable residents should call by Friday so another day can be arranged.', wrong: [['当日まで待って、作業員にだけメールする。', 'The notice asks for a call to the company in advance, by Friday.'], ['点検の十五分前に、必ず料金を払う。', 'Fifteen minutes is the inspection duration, and no payment on the spot is required.'], ['何も連絡せず、別の日に勝手に点検を始める。', 'The alternative date must be discussed with the company; residents do not start the inspection themselves.']], evidence: '今週の金曜日までに管理会社へ電話してください。別の日をご相談します。' },
    { prompt: '点検に来る作業員について、正しいものはどれですか。', answer: '会社名の入った名札を付けている。', reason: 'The notice identifies workers by their company-name badges.', wrong: [['どの部屋でも一時間作業する。', 'The expected inspection time is about fifteen minutes per room.'], ['点検を始める前に、その場で料金を集める。', 'The announcement expressly says there is no payment on the spot.'], ['三階の部屋には午前中にだけ来る。', 'The third and fourth floors are scheduled for the afternoon.']], evidence: '作業員は、会社名の入った名札を付けています。' },
  ]);
listen('lx-more-rail-pass', 'Choosing a rail ticket for one afternoon', 'transport', 'listening-points',
  '客：午後、市内を何度か移動する予定です。一日券はありますか。\n係：はい。六百円の一日券なら、この会社の電車に今日一日、何回でも乗れます。バスには使えません。\n客：一回だけ乗ると、いくらですか。\n係：どの駅まででも二百円です。四回以上乗るなら、一日券のほうが安くなります。\n客：今日は四回乗る予定なので、一日券を一枚お願いします。\n係：ありがとうございます。券売機では買えないので、次回もこちらの窓口でお求めください。窓口は午後七時までです。\n客：分かりました。帰りも、この券を使います。',
  'Passenger: I plan to make several trips around the city this afternoon. Do you have a day pass? Clerk: Yes. A 600-yen pass lets you ride this company’s trains as many times as you want today. It does not work on buses. Passenger: What does one ride cost? Clerk: Two hundred yen to any station. For four or more rides, the day pass is cheaper. Passenger: I plan four rides today, so one day pass, please. Clerk: Thank you. It is not sold at ticket machines, so please use this counter next time too. The counter is open until 7 p.m. Passenger: Understood. I will use this pass on the way back too.', [
    { prompt: '客が一日券を選んだ理由は何ですか。', answer: '今日は四回乗るので、普通の切符より安いから。', reason: 'Four single rides cost 800 yen, while the chosen pass costs 600 yen.', wrong: [['一日券なら、明日のバスにも乗れるから。', 'The pass is for today’s trains on this company, not tomorrow or buses.'], ['一回だけ乗っても、一日券のほうが安いから。', 'One single ride costs 200 yen, less than a 600-yen day pass.'], ['窓口が午後まで開かないから。', 'The counter is already serving the customer; its closing time is seven.']], evidence: '今日は四回乗る予定なので、一日券を一枚お願いします。' },
    { prompt: 'この一日券で乗れるのは、どれですか。', answer: '今日、この会社の電車。', reason: 'The scope is this company’s trains during the current day.', wrong: [['明日、この会社の電車だけ。', 'The clerk specifies today, not tomorrow.'], ['今日、どの会社のバスでも。', 'The pass cannot be used on buses and is not for every company.'], ['今日の電車は、帰りの一回だけ。', 'The pass allows unlimited rides today, not just one return ride.']], evidence: 'この会社の電車に今日一日、何回でも乗れます。バスには使えません。' },
    { prompt: '一日券は、どこで買いますか。', answer: '午後七時まで開いている窓口。', reason: 'The clerk says the pass is sold at the counter, which remains open until seven.', wrong: [['駅の券売機だけ。', 'The pass is expressly unavailable from ticket machines.'], ['バスの中で、降りるとき。', 'This is a train pass sold at the station counter, not a bus fare.'], ['次の日の朝に、同じ客から。', 'The clerk directs future purchases to the same counter, not to another passenger.']], evidence: '券売機では買えないので、次回もこちらの窓口でお求めください。窓口は午後七時までです。' },
  ]);
listen('lx-more-exhibition-info', 'A phone inquiry about a special exhibition', 'culture', 'listening-points',
  '客：今度の写真展について伺いたいんですが。美術館の入場券だけで見られますか。\n係：写真展は特別展なので、別の券が必要です。特別展の券は千円で、常設展も見られます。常設展だけの券は四百円です。\n客：写真展の中で、写真を撮ってもいいですか。\n係：申し訳ありません。特別展では撮影できません。常設展には撮影できる作品もありますが、入口の表示で確認してください。\n客：分かりました。午後五時ごろでも入れますか。\n係：閉館は午後六時ですが、最後の入場は五時半です。特別展は三十分ぐらいかかりますので、時間に余裕を持ってお越しください。',
  'Caller: I would like to ask about the upcoming photography exhibition. Can I see it with just the museum’s admission ticket? Staff: It is a special exhibition, so a different ticket is needed. The 1,000-yen special-exhibition ticket includes the permanent collection too. A ticket for only the permanent collection costs 400 yen. Caller: May I take photos inside the photography exhibition? Staff: Sorry, photography is not allowed in the special exhibition. Some works in the permanent collection may be photographed; check the signs at the entrance. Caller: Understood. Can I enter around 5 p.m.? Staff: We close at six, but last admission is 5:30. The special exhibition takes about thirty minutes, so please allow enough time.', [
    { prompt: '写真展と常設展の両方を見たい人は、どの券を買えばいいですか。', answer: '千円の特別展の券。', reason: 'The special-exhibition ticket also includes entry to the permanent collection.', wrong: [['四百円の常設展だけの券。', 'That ticket excludes the special photography exhibition.'], ['千円と四百円の券を、必ず両方買う。', 'The 1,000-yen ticket already includes the permanent collection, so both are not required.'], ['入場券を買わず、入口の表示だけ見る。', 'The exhibition requires a special-exhibition ticket.']], evidence: '特別展の券は千円で、常設展も見られます。' },
    { prompt: '作品の撮影について、正しいものはどれですか。', answer: '特別展では撮れないが、常設展には撮れる作品もある。', reason: 'The staff distinguishes the complete photography ban in the special exhibition from limited permission in the permanent collection.', wrong: [['どちらの展示でも、全部の作品を撮れる。', 'Special-exhibition photography is prohibited, and permission in the permanent collection is limited to some works.'], ['特別展の券があれば、写真展の中でも撮れる。', 'Buying a ticket does not remove the photography restriction.'], ['常設展では撮れないが、写真展では撮れる。', 'This reverses the rules.']], evidence: '特別展では撮影できません。常設展には撮影できる作品もあります' },
    { prompt: '美術館に最後に入れるのは、何時ですか。', answer: '午後五時半。', reason: 'Last admission is 5:30 p.m., earlier than the 6 p.m. closing time.', wrong: [['午後六時。', 'Six is closing time; visitors must enter by five thirty.'], ['午後五時だけ。', 'The caller mentions five, but the actual last-admission time is five thirty.'], ['午後六時半。', 'This is after the stated closing time.']], evidence: '最後の入場は五時半です。' },
  ]);
listen('lx-more-books', 'Deciding which books to buy', 'shopping', 'listening-outline',
  '以前、私は書店で安い本を見つけると、必要かどうか考えずに買っていました。いつか読むつもりでしたが、読まないままの本が増えて、棚がいっぱいになりました。そこで、今は買う前に、図書館で同じ本を探すようにしています。借りられれば、少し読んでから、自分で持っていたい本か考えます。図書館にない場合は、店で目次をよく確認します。この方法にしてから、買う数は減りましたが、買った本を読むことが増えました。本を買うのをやめたわけではありません。値段だけで決めず、自分が本当に使うか、考える時間を持つようになったのです。',
  'I used to buy a book whenever I found it cheaply at a bookstore without considering whether I needed it. I intended to read it someday, but unread books accumulated and filled my shelves. Now, before buying, I look for the same book at the library. If I can borrow it, I read a little and consider whether it is a book I want to own. If the library does not have it, I carefully check the contents at the shop. Since changing my approach, I buy fewer books but read more of the books I buy. I have not stopped buying books. Rather than deciding by price alone, I now take time to consider whether I will actually use them.', [
    { prompt: 'この話の主な内容は何ですか。', answer: '本を買う前に、自分に必要か考える方法。', reason: 'The whole talk describes changing from price-driven purchases to checking whether a book is useful and worth owning.', wrong: [['図書館に本を全部寄付する方法。', 'The speaker uses library borrowing to help decide, not to donate all owned books.'], ['本を一冊も買わない生活。', 'The speaker expressly says buying books has not stopped.'], ['安い本をできるだけ多く集める方法。', 'That resembles the earlier habit which the speaker has changed.']], evidence: '値段だけで決めず、自分が本当に使うか、考える時間を持つようになったのです。' },
    { prompt: '以前の買い方には、どんな問題がありましたか。', answer: '読まないままの本が増え、棚がいっぱいになった。', reason: 'Books bought because they were cheap often remained unread and filled the shelves.', wrong: [['安い本が一冊も見つからなかった。', 'The speaker regularly found and bought inexpensive books.'], ['図書館で借りた本を返せなくなった。', 'Borrowing is part of the later method; no failure to return books is described.'], ['買った本を読む時間が、必ず長すぎた。', 'The stated problem is unread books, not books taking too long to read.']], evidence: '読まないままの本が増えて、棚がいっぱいになりました。' },
    { prompt: '今の買い方について、この人はどう考えていますか。', answer: '数は減っても、買った本を読むことが増えてよかった。', reason: 'The described improvement is fewer purchases paired with more reading of the purchased books.', wrong: [['図書館にない本は、内容を見ずに必ず買うべきだ。', 'When a book is unavailable at the library, the speaker checks its contents in the shop.'], ['本の値段だけを見れば十分だ。', 'The final point explicitly rejects deciding on price alone.'], ['本を持つことは、すべて無駄だ。', 'The speaker still buys books worth owning and does not condemn all ownership.']], evidence: '買う数は減りましたが、買った本を読むことが増えました。' },
  ]);
listen('lx-more-park-habit', 'Keeping a small park-care habit', 'nature', 'listening-outline',
  '近所の公園で、ごみ拾いの活動に参加したことがあります。その日はきれいになりましたが、しばらくすると、またごみが気になるようになりました。初めは、もっと大きな活動を計画しなければと思いました。でも、毎週何時間も集まるのは、私には難しかったのです。今は、帰り道に公園を通る日に、五分だけごみを拾っています。一度に拾える量は少ないですが、無理なく続けられます。ときどき近所の人も一緒に拾ってくれて、短い会話をするようになりました。一人ですべてを解決できるとは思っていません。ただ、大きな計画を立てるだけでなく、自分が続けられる小さなことから始めるのも大切だと感じています。',
  'I once participated in a litter-picking activity at a neighborhood park. It was clean that day, but after a while I began noticing litter again. At first I thought we needed to plan a bigger activity. However, gathering for hours every week would be difficult for me. Now, on days when I pass through the park on my way home, I pick up litter for just five minutes. I collect only a little each time, but can continue without overdoing it. Sometimes neighbors join in, and we have begun sharing short conversations. I do not think I can solve everything alone. But I feel it matters to start with something small I can continue, rather than only making a big plan.', [
    { prompt: 'この話で、最も伝えたいことは何ですか。', answer: '大きな計画だけでなく、続けられる小さな行動も大切だ。', reason: 'The concluding message values a manageable ongoing action instead of merely planning something large.', wrong: [['公園の問題は、一人で必ず全部解決できる。', 'The speaker explicitly rejects the belief that one person can solve everything.'], ['活動には、毎週何時間も参加しなければならない。', 'Long weekly gatherings were difficult, so the speaker chose a shorter habit.'], ['ごみがまた増えたら、何もしないほうがいい。', 'The speaker responds to recurring litter by taking a small continuing action.']], evidence: '自分が続けられる小さなことから始めるのも大切だと感じています。' },
    { prompt: 'この人が今の方法を選んだのは、なぜですか。', answer: '長い活動は難しくても、五分なら無理なく続けられるから。', reason: 'The change fits the speaker’s available time: hours were difficult, but brief efforts are sustainable.', wrong: [['公園を通ると、必ずお金がもらえるから。', 'No payment is mentioned; the reason is being able to keep doing it.'], ['毎回、全部のごみを拾えるから。', 'The speaker says the amount collected each time is small.'], ['近所の人から、毎日五時間するように言われたから。', 'No such instruction occurs, and the actual duration is five minutes on days the speaker passes through.']], evidence: '一度に拾える量は少ないですが、無理なく続けられます。' },
    { prompt: 'ごみを拾うようになってから、どんな変化もありましたか。', answer: '近所の人と一緒に拾い、短い会話をするようになった。', reason: 'Alongside the litter-picking habit, some neighbors have joined and begun talking with the speaker.', wrong: [['公園へ行く道を完全に変えた。', 'The speaker still passes through the park on the way home.'], ['近所の人とは、全く話さなくなった。', 'The passage describes the opposite: brief conversations have started.'], ['公園のごみが、永久になくなった。', 'No permanent solution is claimed; the speaker explicitly acknowledges limits.']], evidence: '近所の人も一緒に拾ってくれて、短い会話をするようになりました。' },
  ]);
listen('lx-more-travel-expressions', 'Useful expressions during a journey', 'travel', 'listening-expression',
  '三つの場面で、目的に合う言い方を考えてください。\n場面一。あなたは駅で、三番乗り場の場所が分からず困っています。近くの係の人に、そこまでの行き方を聞きたいと思っています。\n場面二。あなたは混んだバスに乗っています。次の停留所で降りたいのですが、通路に人がいて通れません。その人に、丁寧に通してほしいと頼みたいと思っています。\n場面三。あなたはホテルに泊まっています。明日は早い電車に乗るので、午前六時半にチェックアウトしてもよいか、受付に確認したいと思っています。',
  'Consider a suitable expression for each situation. Situation 1: you are at a station and do not know where platform three is. You want to ask a nearby staff member how to get there. Situation 2: you are on a crowded bus and want to get off at the next stop, but someone is blocking the aisle. You want to politely ask them to let you through. Situation 3: you are staying at a hotel and taking an early train tomorrow. You want to check with reception whether you may check out at 6:30 a.m.', [
    { prompt: '場面一で、乗り場への行き方を聞くなら、何と言いますか。', answer: 'すみません、三番乗り場へはどう行けばいいですか。', reason: 'This politely asks for directions to the specific platform in the situation.', wrong: [['三番乗り場から電車が出たか、教えてください。', 'This asks whether a train has departed, not how to reach the platform.'], ['三番乗り場で、私を必ず待ってください。', 'This tells the staff member to wait there rather than requesting directions.'], ['三番乗り場から、もう帰ってきました。', 'This reports a completed return and does not ask for directions.']], evidence: 'そこまでの行き方を聞きたいと思っています。' },
    { prompt: '場面二で、通してほしいと頼むなら、何と言いますか。', answer: 'すみません、次で降りますので、通していただけますか。', reason: 'The phrase states the reason and politely requests room to pass.', wrong: [['次の停留所には、誰も降りないでください。', 'This prohibits others from getting off instead of asking to pass.'], ['このバスに乗ってもよろしいですか。', 'The speaker is already on the bus and wants to get off, not board.'], ['通路は空いているので、そのままで大丈夫です。', 'The situation says the aisle is blocked, so leaving it unchanged will not help.']], evidence: 'その人に、丁寧に通してほしいと頼みたいと思っています。' },
    { prompt: '場面三で、受付に確認するなら、何と言いますか。', answer: '明日は六時半にチェックアウトしてもよろしいですか。', reason: 'This respectfully checks permission for the required early checkout tomorrow.', wrong: [['昨日は六時半にチェックインしました。', 'This reports yesterday’s check-in, rather than asking about tomorrow’s checkout.'], ['明日の電車は、受付で運転していただけますか。', 'The hotel desk cannot be asked to operate the train; the need is an early checkout.'], ['六時半に来た人は、ホテルに入れないでください。', 'This requests denying others entry, not checking the speaker’s checkout arrangements.']], evidence: '午前六時半にチェックアウトしてもよいか、受付に確認したい' },
  ]);
listen('lx-more-work-expressions', 'Borrowing, extending a deadline, and correcting a figure', 'work', 'listening-expression',
  '仕事中の三つの場面です。\n場面一。あなたは明日の午前十時から正午まで、説明会でプロジェクターを使いたいと思っています。同僚が持っている物を、その時間だけ借りたいと思っています。\n場面二。今日中に提出する予定だった報告書に、確認が必要なところが見つかりました。上司に理由を説明して、提出を明日の朝まで待ってもらいたいと思っています。\n場面三。配った資料の二ページ目に、数の間違いがありました。十五と書いてありますが、正しくは五十です。会議の参加者に謝って、数字を訂正したいと思っています。',
  'These are three workplace situations. Situation 1: you need a projector for an information session tomorrow from 10 a.m. to noon. You want to borrow a colleague’s projector for that period. Situation 2: a report due today contains a point that needs checking. You want to explain to your supervisor and ask to postpone submission until tomorrow morning. Situation 3: there is an incorrect number on page two of the distributed materials: it says fifteen, but the correct number is fifty. You want to apologize to the participants and correct it.', [
    { prompt: '場面一で、同僚に借りる許可を求めるなら、何と言いますか。', answer: '明日の十時から十二時まで、このプロジェクターを借りてもいいですか。', reason: 'This asks to borrow the projector for exactly the required period.', wrong: [['昨日お借りしたプロジェクターを返します。', 'This concerns returning a past loan, not requesting tomorrow’s use.'], ['明日の午後、このプロジェクターを買ってください。', 'The speaker wants to borrow in the morning, not ask the colleague to buy it in the afternoon.'], ['十時までに、このプロジェクターを捨ててもいいですか。', 'This asks permission to discard the item, not borrow it.']], evidence: 'その時間だけ借りたいと思っています。' },
    { prompt: '場面二で、提出を待ってもらうなら、何と言いますか。', answer: '申し訳ありません。確認に時間がかかるので、提出を明日の朝まで待っていただけますか。', reason: 'This explains why the report is delayed and respectfully asks for the requested extension.', wrong: [['もう確認が終わったので、今日中に提出しました。', 'This falsely says checking and submission are completed.'], ['確認する必要はありません。このまま提出します。', 'The scenario says a point needs verification, so bypassing it does not address the request.'], ['明日の朝までに、報告書を捨てていただけますか。', 'The speaker needs more time to submit a corrected report, not to have it discarded.']], evidence: '提出を明日の朝まで待ってもらいたいと思っています。' },
    { prompt: '場面三で、数字を訂正するなら、何と言いますか。', answer: '申し訳ありません。二ページ目の十五は、正しくは五十です。訂正をお願いします。', reason: 'This apologizes and replaces the incorrect fifteen with the correct fifty on the stated page.', wrong: [['二ページ目の五十は、正しくは十五です。', 'This reverses the incorrect and correct numbers.'], ['数字は全部正しいので、何も直さないでください。', 'The scenario explicitly identifies an error that must be corrected.'], ['一ページ目の十五を、明日の朝まで待ってください。', 'This uses the wrong page and a waiting request rather than correcting the figure.']], evidence: '十五と書いてありますが、正しくは五十です。' },
  ]);
listen('lx-more-friend-replies', 'Replies to an invitation, weather talk, and an apology', 'communication', 'listening-response',
  '三人の友達の発言を聞いて、返事を選んでください。\n発言一。「今度の土曜日、一緒に映画を見に行かない？」\n発言二。「今日はいい天気ですね。昨日は雨で大変でしたけど。」\n発言三。「ごめんね。急に仕事が入って、今日の約束に行けなくなっちゃった。」',
  'Listen to three friends and choose replies. Utterance 1: “Would you like to go see a film with me this Saturday?” Utterance 2: “The weather is nice today. Yesterday’s rain made things difficult, though.” Utterance 3: “Sorry. Work suddenly came up, and I can no longer make our plans today.”', [
    { prompt: '発言一に対して、誘いを受けるなら、どれですか。', answer: 'いいね。土曜日の午後なら行けるよ。', reason: 'This accepts the invitation and gives an available time on the proposed day.', wrong: [['映画館の入口は、もう掃除しました。', 'This reports cleaning, not acceptance of a movie invitation.'], ['その映画は、昨日から返せません。', 'This mentions inability to return a film and does not accept the invitation.'], ['土曜日は絶対に行けないから、今回はやめておくね。', 'This is a clear refusal; the question asks for acceptance.']], evidence: '今度の土曜日、一緒に映画を見に行かない？' },
    { prompt: '発言二への返事として、最も自然なものはどれですか。', answer: 'そうですね。今日は晴れて、歩くのも気持ちがいいですね。', reason: 'This responds to the current pleasant weather and continues the same small-talk topic.', wrong: [['どういたしまして。映画の券をありがとうございます。', 'No favor or movie-ticket thanks appear in this utterance.'], ['申し訳ありません。予約は午後三時でした。', 'This introduces an unrelated appointment apology.'], ['いいえ、その本はまだ返していません。', 'This answers a question about returning a book, not weather talk.']], evidence: '今日はいい天気ですね。' },
    { prompt: '発言三に対して、相手を責めずに返事をするなら、どれですか。', answer: '分かった。大丈夫だよ。また都合のいい日に会おう。', reason: 'This acknowledges the cancellation kindly and suggests meeting another day without blaming the friend.', wrong: [['来てくれてありがとう。今、隣に座ってね。', 'The friend has said they cannot come, so thanking them for arriving contradicts the situation.'], ['おめでとう。約束に間に合ってよかったね。', 'The friend has canceled, rather than arrived in time for congratulations.'], ['仕事より約束が先でしょ。今すぐ来て。', 'This pressures and reproaches the friend, contrary to the requested non-blaming response.']], evidence: '今日の約束に行けなくなっちゃった。' },
  ]);
listen('lx-more-service-replies', 'Responding to a wrong item, an appointment change, and a name check', 'services', 'listening-response',
  '店や受付での三つの発言です。相手の目的に合う返事を考えてください。\n発言一。客が店員に言います。「注文したのは青いマグカップですが、白い物が届きました。確認していただけますか。」\n発言二。客が受付で言います。「来週の火曜日の予約を、午前から午後に変更したいんですが。」\n発言三。受付の人があなたに聞きます。「お名前は、この漢字で合っていますか。」',
  'These are three utterances in shops or at reception desks. Consider a reply matching the speaker’s purpose. Utterance 1, a customer to a clerk: “I ordered a blue mug, but a white one arrived. Could you check it?” Utterance 2, a customer at reception: “I would like to move next Tuesday’s appointment from morning to afternoon.” Utterance 3, a receptionist to you: “Are these the correct kanji for your name?”', [
    { prompt: '発言一に対して、注文を確認する店員の返事として、どれが適切ですか。', answer: '申し訳ございません。注文内容を確認しますので、注文番号を教えていただけますか。', reason: 'This acknowledges the problem and requests information needed to check the order, without assuming an outcome before checking.', wrong: [['青い物と白い物は同じですから、確認しません。', 'This dismisses the reported color mismatch instead of investigating it.'], ['ご注文は午後に変更しておきました。', 'The issue is the delivered color, not the time of an appointment or order.'], ['こちらこそ、ご確認いただきありがとうございました。', 'The customer is asking the clerk to check; thanking them for a completed check reverses that situation.']], evidence: '注文したのは青いマグカップですが、白い物が届きました。確認していただけますか。' },
    { prompt: '発言二に対して、予約の変更を確認する返事として、どれが適切ですか。', answer: '承知しました。火曜日の午後の空き時間を確認します。', reason: 'This addresses the requested shift to Tuesday afternoon and checks availability before promising a booking.', wrong: [['では、月曜日の午前の予約を、そのままにします。', 'The request concerns Tuesday and a move from morning to afternoon.'], ['午後のご予約を、火曜日の午前に変更します。', 'This reverses the requested direction of the change.'], ['マグカップの色を確認してから、お名前を消します。', 'This combines unrelated subjects and does not help change the appointment.']], evidence: '来週の火曜日の予約を、午前から午後に変更したい' },
    { prompt: '発言三に対して、名前の漢字が正しいことを伝えるなら、どれですか。', answer: 'はい、その漢字で合っています。', reason: 'This directly confirms the written kanji for the speaker’s name, as the question requests.', wrong: [['いいえ、予約は火曜日ではありません。', 'This denies an appointment date rather than confirming the name’s spelling.'], ['青い物を注文したので、白い物は不要です。', 'This concerns a product color, not the written name.'], ['明日の午後なら、電話をかけられます。', 'This gives phone availability rather than confirming the kanji.']], evidence: 'お名前は、この漢字で合っていますか。' },
  ]);
